export interface Concert {
  id: string;
  band: string;
  date: string; // ISO format YYYY-MM-DD for storage/sorting
  displayDate?: string; // Original format for display preference if needed, mostly used for initial import
  city: string;
  event: string;
  artists: number;
  cost: number;
  year: number;
}

export type SortField = 'date' | 'cost' | 'band';
export type SortOrder = 'asc' | 'desc';

export interface FilterState {
  search: string;
  minYear: string;
  maxYear: string;
}

import { useState, useEffect } from 'react';
import { Concert } from '../types';
import { INITIAL_CONCERTS } from '../constants';

export const useConcerts = () => {
  const [concerts, setConcerts] = useState<Concert[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  // Load from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('concerts_v1');
    if (saved) {
      try {
        setConcerts(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse saved concerts", e);
        setConcerts(INITIAL_CONCERTS);
      }
    } else {
      setConcerts(INITIAL_CONCERTS);
    }
    setIsLoaded(true);
  }, []);

  // Save to local storage whenever concerts change
  useEffect(() => {
    if (isLoaded) {
      localStorage.setItem('concerts_v1', JSON.stringify(concerts));
    }
  }, [concerts, isLoaded]);

  const addConcert = (concert: Omit<Concert, 'id'>) => {
    const newConcert = {
      ...concert,
      id: crypto.randomUUID(),
    };
    setConcerts(prev => [...prev, newConcert]);
  };

  const updateConcert = (id: string, updated: Partial<Concert>) => {
    setConcerts(prev => prev.map(c => (c.id === id ? { ...c, ...updated } : c)));
  };

  const deleteConcert = (id: string) => {
    setConcerts(prev => prev.filter(c => c.id !== id));
  };

  return { concerts, addConcert, updateConcert, deleteConcert };
};

