import React, { useState, useEffect } from 'react';
import { X, Calendar, MapPin, Users, Ticket, Music2, PartyPopper } from 'lucide-react';
import { Concert } from '../types';

interface ConcertFormProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: Omit<Concert, 'id'>) => void;
  initialData?: Concert;
}

export const ConcertForm: React.FC<ConcertFormProps> = ({ isOpen, onClose, onSubmit, initialData }) => {
  const [formData, setFormData] = useState({
    band: '',
    date: '',
    city: '',
    event: '',
    artists: 1,
    cost: 0,
  });

  useEffect(() => {
    if (initialData) {
      setFormData({
        band: initialData.band,
        date: initialData.date,
        city: initialData.city,
        event: initialData.event,
        artists: initialData.artists,
        cost: initialData.cost,
      });
    } else {
      setFormData({
        band: '',
        date: new Date().toISOString().split('T')[0],
        city: '',
        event: 'Concerto',
        artists: 1,
        cost: 0,
      });
    }
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const dateObj = new Date(formData.date);
    const year = dateObj.getFullYear();

    onSubmit({
      ...formData,
      year,
    });
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm">
      <div className="bg-slate-900 border border-slate-700 w-full max-w-md rounded-2xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
        <div className="p-4 border-b border-slate-800 flex justify-between items-center bg-slate-800/50">
          <h2 className="text-xl font-bold text-white">
            {initialData ? 'Modifica Concerto' : 'Nuovo Concerto'}
          </h2>
          <button onClick={onClose} className="text-slate-400 hover:text-white transition-colors">
            <X size={24} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">

          <div className="space-y-1">
            <label className="text-xs uppercase font-semibold text-slate-400 flex items-center gap-2">
              <Music2 size={14} /> Band / Artista
            </label>
            <input
              required
              type="text"
              value={formData.band}
              onChange={(e) => setFormData({ ...formData, band: e.target.value })}
              className="w-full bg-slate-950 border border-slate-700 rounded-lg p-3 text-white focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
              placeholder="Es. Simple Plan, Salmo..."
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-xs uppercase font-semibold text-slate-400 flex items-center gap-2">
                <Calendar size={14} /> Data
              </label>
              <input
                required
                type="date"
                value={formData.date}
                onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                className="w-full bg-slate-950 border border-slate-700 rounded-lg p-3 text-white focus:ring-2 focus:ring-indigo-500 outline-none"
              />
            </div>
             <div className="space-y-1">
              <label className="text-xs uppercase font-semibold text-slate-400 flex items-center gap-2">
                <Ticket size={14} /> Costo (€)
              </label>
              <input
                required
                type="number"
                step="0.01"
                min="0"
                value={formData.cost}
                onChange={(e) => setFormData({ ...formData, cost: parseFloat(e.target.value) })}
                className="w-full bg-slate-950 border border-slate-700 rounded-lg p-3 text-white focus:ring-2 focus:ring-indigo-500 outline-none"
              />
