import React from 'react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell, CartesianGrid } from 'recharts';
import { Concert } from '../types';
import { TrendingUp, DollarSign, Calendar, Music } from 'lucide-react';

interface StatisticsProps {
  concerts: Concert[];
}

export const Statistics: React.FC<StatisticsProps> = ({ concerts }) => {
  // 1. Calculate Summary Stats
  const totalSpent = concerts.reduce((acc, c) => acc + c.cost, 0);
  const totalConcerts = concerts.length;
  const totalArtists = concerts.reduce((acc, c) => acc + c.artists, 0);

  // 2. Prepare Chart Data (Spend per Year)
  const years = Array.from(new Set(concerts.map(c => c.year))).sort((a, b) => a - b);
  const dataByYear = years.map(year => {
    const yearlyConcerts = concerts.filter(c => c.year === year);
    return {
      year,
      spent: yearlyConcerts.reduce((acc, c) => acc + c.cost, 0),
      count: yearlyConcerts.length
    };
  });

  // 3. Top Artists Logic
  const artistCounts: Record<string, number> = {};
  concerts.forEach(c => {
    // Split by comma, clean whitespace, normalize case
    const artists = c.band.split(',').map(s => s.trim());
    artists.forEach(artist => {
      const name = artist; // Could normalize toLowerCase if needed
      artistCounts[name] = (artistCounts[name] || 0) + 1;
    });
  });

  const topArtists = Object.entries(artistCounts)
    .sort(([, a], [, b]) => b - a)
    .slice(0, 5); // Top 5

  return (
    <div className="space-y-6 pb-24 animate-in fade-in slide-in-from-bottom-4 duration-500">

      {/* KPI Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-slate-800/50 backdrop-blur-sm border border-slate-700 p-4 rounded-2xl">
          <div className="flex items-center gap-2 text-indigo-400 mb-2">
            <DollarSign size={18} />
            <span className="text-xs font-bold uppercase tracking-wider">Totale Speso</span>
          </div>
          <div className="text-2xl font-bold text-white">€{totalSpent.toFixed(2)}</div>
        </div>
        <div className="bg-slate-800/50 backdrop-blur-sm border border-slate-700 p-4 rounded-2xl">
          <div className="flex items-center gap-2 text-purple-400 mb-2">
            <Calendar size={18} />
            <span className="text-xs font-bold uppercase tracking-wider">Concerti</span>
          </div>
          <div className="text-2xl font-bold text-white">{totalConcerts}</div>
        </div>
        <div className="bg-slate-800/50 backdrop-blur-sm border border-slate-700 p-4 rounded-2xl">
          <div className="flex items-center gap-2 text-pink-400 mb-2">
            <Music size={18} />
            <span className="text-xs font-bold uppercase tracking-wider">Artisti Visti</span>
          </div>
          <div className="text-2xl font-bold text-white">{totalArtists}</div>
        </div>
        <div className="bg-slate-800/50 backdrop-blur-sm border border-slate-700 p-4 rounded-2xl">
          <div className="flex items-center gap-2 text-emerald-400 mb-2">
            <TrendingUp size={18} />
            <span className="text-xs font-bold uppercase tracking-wider">Media Costo</span>
          </div>
          <div className="text-2xl font-bold text-white">€{(totalSpent / totalConcerts || 0).toFixed(2)}</div>
        </div>
      </div>

      {/* Charts Row */}
      <div className="grid md:grid-cols-2 gap-6">

        {/* Money per Year */}
        <div className="bg-slate-800 border border-slate-700 rounded-2xl p-6 shadow-xl">
          <h3 className="text-lg font-bold text-white mb-6">Spesa per Anno</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={dataByYear}>
                <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
                <XAxis dataKey="year" stroke="#94a3b8" tick={{fontSize: 12}} />
                <YAxis stroke="#94a3b8" tick={{fontSize: 12}} tickFormatter={(val) => `€${val}`} />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', color: '#f8fafc' }}
                  itemStyle={{ color: '#818cf8' }}
                  formatter={(value: number) => [`€${value.toFixed(2)}`, 'Spesa']}
                />
                <Bar dataKey="spent" radius={[4, 4, 0, 0]}>
                  {dataByYear.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill="url(#colorGradient)" />
                  ))}
                </Bar>
                <defs>
                  <linearGradient id="colorGradient" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#6366f1" stopOpacity={0.8}/>
                    <stop offset="95%" stopColor="#8b5cf6" stopOpacity={0.8}/>
                  </linearGradient>
                </defs>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Top Artists List */}
        <div className="bg-slate-800 border border-slate-700 rounded-2xl p-6 shadow-xl">
          <h3 className="text-lg font-bold text-white mb-4">Artisti più visti</h3>
          <div className="space-y-4">
            {topArtists.map(([artist, count], idx) => (
              <div key={idx} className="flex items-center justify-between p-3 bg-slate-700/50 rounded-lg hover:bg-slate-700 transition-colors">
                <div className="flex items-center gap-3">
                  <span className={`flex items-center justify-center w-8 h-8 rounded-full font-bold text-sm ${idx === 0 ? 'bg-yellow-500/20 text-yellow-400' : 'bg-slate-600 text-slate-300'}`}>
                    {idx + 1}
                  </span>
                  <span className="font-medium text-white truncate max-w-[150px] sm:max-w-xs">{artist}</span>
                </div>
                <div className="text-sm font-semibold text-indigo-300">{count} volte</div>
              </div>
            ))}
          </div>
        </div>

      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Concert } from '../types';
import { Search, MapPin, Calendar, Edit2, Trash2, ArrowUpDown, Tag } from 'lucide-react';

interface ConcertTableProps {
  concerts: Concert[];
  onEdit: (concert: Concert) => void;
  onDelete: (id: string) => void;
}

export const ConcertTable: React.FC<ConcertTableProps> = ({ concerts, onEdit, onDelete }) => {
  const [search, setSearch] = useState('');
  const [sortField, setSortField] = useState<'date' | 'cost'>('date');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');

  const filteredAndSortedConcerts = useMemo(() => {
    let result = [...concerts];

    // Filter
    if (search) {
      const lowerSearch = search.toLowerCase();
      result = result.filter(
        c => 
          c.band.toLowerCase().includes(lowerSearch) || 
          c.city.toLowerCase().includes(lowerSearch) ||
          c.event.toLowerCase().includes(lowerSearch)
      );
    }

    // Sort
    result.sort((a, b) => {
      let valA, valB;

      if (sortField === 'date') {
        valA = new Date(a.date).getTime();
        valB = new Date(b.date).getTime();
      } else {
        valA = a.cost;
        valB = b.cost;
      }

      return sortOrder === 'asc' ? valA - valB : valB - valA;
    });

    return result;
  }, [concerts, search, sortField, sortOrder]);

  const toggleSort = (field: 'date' | 'cost') => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder('desc'); // default to high-to-low/newest-to-oldest
    }
  };

  const formatDate = (dateStr: string) => {
    try {
      return new Date(dateStr).toLocaleDateString('it-IT', { day: 'numeric', month: 'short', year: 'numeric' });
    } catch {
      return dateStr;
    }
  };

  return (
    <div className="pb-24 space-y-4">

      {/* Search and Filters Bar */}
      <div className="sticky top-0 z-30 bg-slate-900/80 backdrop-blur-md pt-4 pb-4">
        <div className="flex gap-2 mb-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input
              type="text"
              placeholder="Cerca band, città, evento..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full bg-slate-800 border border-slate-700 text-white rounded-xl py-3 pl-10 pr-4 focus:ring-2 focus:ring-indigo-500 outline-none"
            />
          </div>
        </div>

        <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
          <button 
            onClick={() => toggleSort('date')}
            className={`flex items-center gap-1 px-4 py-2 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${
              sortField === 'date' ? 'bg-indigo-600 text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'
            }`}
          >
            <Calendar size={14} /> Data {sortField === 'date' && (sortOrder === 'asc' ? '↑' : '↓')}
          </button>
          <button 
            onClick={() => toggleSort('cost')}
            className={`flex items-center gap-1 px-4 py-2 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${
              sortField === 'cost' ? 'bg-indigo-600 text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'
            }`}
          >
            <Tag size={14} /> Costo {sortField === 'cost' && (sortOrder === 'asc' ? '↑' : '↓')}
          </button>
        </div>
      </div>

      {/* List */}
      <div className="space-y-3">
        {filteredAndSortedConcerts.length === 0 ? (
          <div className="text-center text-slate-500 py-10">
            Nessun concerto trovato.
          </div>
        ) : (
          filteredAndSortedConcerts.map((concert) => (
            <div 
              key={concert.id}
              className="group bg-slate-800 border border-slate-700 rounded-xl p-4 hover:border-indigo-500/50 transition-all shadow-sm hover:shadow-lg relative overflow-hidden"
            >
              {/* Event Type Badge */}
              <div className="absolute top-0 right-0 bg-slate-700 px-3 py-1 rounded-bl-xl text-[10px] font-bold uppercase text-slate-300 tracking-wider">
                {concert.event}
              </div>

              <div className="flex justify-between items-start mt-2">
                <div>
                  <h3 className="text-lg font-bold text-white leading-tight mb-1">{concert.band}</h3>
                  <div className="flex items-center gap-4 text-sm text-slate-400">
                    <span className="flex items-center gap-1"><Calendar size={14}/> {formatDate(concert.date)}</span>
                    <span className="flex items-center gap-1"><MapPin size={14}/> {concert.city}</span>
                  </div>
                </div>
              </div>

              <div className="mt-4 flex justify-between items-end border-t border-slate-700/50 pt-3">
                <div className="text-indigo-400 font-bold text-lg">
                  {concert.cost === 0 ? 'Gratis' : `€${concert.cost.toFixed(2)}`}
                </div>

                <div className="flex gap-2">
                  <button 
                    onClick={() => onEdit(concert)}
                    className="p-2 text-slate-400 hover:text-white hover:bg-slate-700 rounded-lg transition-colors"
                  >
                    <Edit2 size={18} />
                  </button>
                  <button 
                    onClick={() => {
                      if (window.confirm('Sei sicuro di voler eliminare questo concerto?')) {
                        onDelete(concert.id);
                      }
                    }}
                    className="p-2 text-slate-400 hover:text-red-400 hover:bg-slate-700 rounded-lg transition-colors"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useConcerts } from './hooks/useConcerts';
import { Navbar } from './components/Navbar';
import { ConcertTable } from './components/ConcertTable';
import { Statistics } from './components/Statistics';
import { ConcertForm } from './components/ConcertForm';
import { Concert } from './types';

function App() {
  const { concerts, addConcert, updateConcert, deleteConcert } = useConcerts();
  const [view, setView] = useState<'list' | 'stats'>('list');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingConcert, setEditingConcert] = useState<Concert | undefined>(undefined);

  const handleAddClick = () => {
    setEditingConcert(undefined);
    setIsFormOpen(true);
  };

  const handleEditClick = (concert: Concert) => {
    setEditingConcert(concert);
    setIsFormOpen(true);
  };

  const handleFormSubmit = (data: Omit<Concert, 'id'>) => {
    if (editingConcert) {
      updateConcert(editingConcert.id, data);
    } else {
      addConcert(data);
    }
  };

  return (
    <div className="min-h-screen bg-slate-900 text-slate-50 selection:bg-indigo-500 selection:text-white">
      <div className="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8 pt-6">

        {/* Header */}
        <header className="mb-6 flex flex-col gap-1">
          <h1 className="text-3xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 to-purple-400">
            Concert Tracker
          </h1>
          <p className="text-slate-400 text-sm">
            Hai partecipato a <strong className="text-white">{concerts.length}</strong> eventi finora.
          </p>
        </header>

        {/* Main Content Area */}
        <main>
          {view === 'list' ? (
            <ConcertTable 
              concerts={concerts} 
              onEdit={handleEditClick} 
              onDelete={deleteConcert} 
            />
          ) : (
            <Statistics concerts={concerts} />
          )}
        </main>
      </div>

      {/* Floating UI Elements */}
      <ConcertForm
        isOpen={isFormOpen}
        onClose={() => setIsFormOpen(false)}
        onSubmit={handleFormSubmit}
        initialData={editingConcert}
      />

      <Navbar 
        currentView={view} 
        setView={setView} 
        onAddClick={handleAddClick} 
      />
    </div>
  );
}

export default App;

export interface Concert {
  id: string;
  band: string;
  date: string; // ISO format YYYY-MM-DD for storage/sorting
  displayDate?: string; // Original format for display preference if needed, mostly used for initial import
  city: string;
  event: string;
  artists: number;
  cost: number;
  year: number;
}

export type SortField = 'date' | 'cost' | 'band';
export type SortOrder = 'asc' | 'desc';
export type PriceRange = 'all' | 'free' | 'under-30' | '30-60' | 'over-60';

export interface FilterState {
  search: string;
  minYear: string;
  maxYear: string;
}

import React, { useState, useMemo } from 'react';
import { Concert, PriceRange } from '../types';
import { Search, MapPin, Calendar, Edit2, Trash2, Tag, Filter, X, ChevronDown, ChevronUp, Mic2 } from 'lucide-react';

interface ConcertTableProps {
  concerts: Concert[];
  onEdit: (concert: Concert) => void;
  onDelete: (id: string) => void;
}

export const ConcertTable: React.FC<ConcertTableProps> = ({ concerts, onEdit, onDelete }) => {
  const [search, setSearch] = useState('');
  const [sortField, setSortField] = useState<'date' | 'cost'>('date');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');

  // Advanced Filters State
  const [showFilters, setShowFilters] = useState(false);
  const [selectedYear, setSelectedYear] = useState<string>('all');
  const [selectedType, setSelectedType] = useState<string>('all');
  const [selectedPrice, setSelectedPrice] = useState<PriceRange>('all');

  // Derive unique options for filters
  const availableYears = useMemo(() => {
    const years = Array.from(new Set(concerts.map(c => c.year))).sort((a, b) => b - a);
    return years;
  }, [concerts]);

  const availableTypes = useMemo(() => {
    const types = Array.from(new Set(concerts.map(c => c.event.toLowerCase().trim())));
    return types.sort();
  }, [concerts]);

  const filteredAndSortedConcerts = useMemo(() => {
    let result = [...concerts];

    // 1. Search Text
    if (search) {
      const lowerSearch = search.toLowerCase();
      result = result.filter(
        c => 
          c.band.toLowerCase().includes(lowerSearch) || 
          c.city.toLowerCase().includes(lowerSearch) ||
          c.event.toLowerCase().includes(lowerSearch)
      );
    }

    // 2. Year Filter
    if (selectedYear !== 'all') {
      result = result.filter(c => c.year === parseInt(selectedYear));
    }

    // 3. Type Filter
    if (selectedType !== 'all') {
      result = result.filter(c => c.event.toLowerCase().trim() === selectedType);
    }

    // 4. Price Filter
    if (selectedPrice !== 'all') {
      switch (selectedPrice) {
        case 'free': result = result.filter(c => c.cost === 0); break;
        case 'under-30': result = result.filter(c => c.cost > 0 && c.cost < 30); break;
        case '30-60': result = result.filter(c => c.cost >= 30 && c.cost <= 60); break;
        case 'over-60': result = result.filter(c => c.cost > 60); break;
      }
    }

    // 5. Sorting
    result.sort((a, b) => {
      let valA, valB;

      if (sortField === 'date') {
        valA = new Date(a.date).getTime();
        valB = new Date(b.date).getTime();
      } else {
        valA = a.cost;
        valB = b.cost;
      }

      return sortOrder === 'asc' ? valA - valB : valB - valA;
    });

    return result;
  }, [concerts, search, sortField, sortOrder, selectedYear, selectedType, selectedPrice]);

  const toggleSort = (field: 'date' | 'cost') => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder('desc'); 
    }
  };

  const getDayAndMonth = (dateStr: string) => {
    try {
      const d = new Date(dateStr);
      const day = d.getDate();
      const month = d.toLocaleDateString('it-IT', { month: 'short' }).toUpperCase();
      const year = d.getFullYear();
      return { day, month, year };
    } catch {
      return { day: '?', month: '???', year: '????' };
    }
  };

  const clearFilters = () => {
    setSearch('');
    setSelectedYear('all');
    setSelectedType('all');
    setSelectedPrice('all');
  };

  const activeFiltersCount = (selectedYear !== 'all' ? 1 : 0) + (selectedType !== 'all' ? 1 : 0) + (selectedPrice !== 'all' ? 1 : 0);

  return (
    <div className="pb-28 space-y-6">

      {/* Search and Sort Bar */}
      <div className="sticky top-0 z-30 pt-4 -mx-2 px-2 pb-4 bg-gradient-to-b from-slate-900 via-slate-900/95 to-transparent">
        <div className="flex flex-col gap-3">

          <div className="flex gap-2">
            <div className="relative flex-1 group">
              <div className="absolute inset-0 bg-gradient-to-r from-indigo-500 to-purple-600 rounded-xl blur opacity-25 group-hover:opacity-40 transition duration-300"></div>
              <div className="relative bg-slate-900 rounded-xl flex items-center border border-slate-700 focus-within:border-indigo-500 transition-colors">
                <Search className="ml-4 text-slate-400" size={20} />
                <input
                  type="text"
                  placeholder="Cerca band, città..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="w-full bg-transparent text-white py-3 px-3 outline-none placeholder-slate-500"
                />
                {search && (
                  <button onClick={() => setSearch('')} className="mr-3 text-slate-500 hover:text-white">
                    <X size={16} />
                  </button>
                )}
              </div>
            </div>

            <button 
              onClick={() => setShowFilters(!showFilters)}
              className={`relative px-4 rounded-xl border transition-all flex items-center justify-center gap-2 ${
                showFilters || activeFiltersCount > 0
                  ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg shadow-indigo-900/20' 
                  : 'bg-slate-800 border-slate-700 text-slate-300 hover:bg-slate-700'
              }`}
            >
              <Filter size={20} />
              {activeFiltersCount > 0 && (
                <span className="absolute -top-2 -right-2 bg-pink-500 text-white text-[10px] font-bold w-5 h-5 flex items-center justify-center rounded-full border border-slate-900">
                  {activeFiltersCount}
                </span>
              )}
            </button>
          </div>

          {/* Expanded Filter Dashboard */}
          <div className={`overflow-hidden transition-all duration-300 ease-in-out ${showFilters ? 'max-h-96 opacity-100' : 'max-h-0 opacity-0'}`}>
            <div className="glass-panel p-4 rounded-xl space-y-4">
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">

                {/* Year Filter */}
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Anno</label>
                  <div className="relative">
                    <select 
                      value={selectedYear}
                      onChange={(e) => setSelectedYear(e.target.value)}
                      className="w-full appearance-none bg-slate-900 border border-slate-700 text-white rounded-lg py-2 px-3 focus:ring-2 focus:ring-indigo-500 outline-none text-sm"
                    >
                      <option value="all">Tutti gli anni</option>
                      {availableYears.map(y => (
                        <option key={y} value={y}>{y}</option>
                      ))}
                    </select>
                    <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" size={14} />
                  </div>
                </div>

                {/* Type Filter */}
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Evento</label>
                  <div className="relative">
                    <select 
                      value={selectedType}
                      onChange={(e) => setSelectedType(e.target.value)}
                      className="w-full appearance-none bg-slate-900 border border-slate-700 text-white rounded-lg py-2 px-3 focus:ring-2 focus:ring-indigo-500 outline-none text-sm capitalize"
                    >
                      <option value="all">Tutti i tipi</option>
                      {availableTypes.map(t => (
                        <option key={t} value={t}>{t}</option>
                      ))}
                    </select>
                    <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" size={14} />
                  </div>
                </div>

                {/* Price Filter */}
                <div className="space-y-1 col-span-2 sm:col-span-1">
                  <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Costo</label>
                  <div className="relative">
                    <select 
                      value={selectedPrice}
                      onChange={(e) => setSelectedPrice(e.target.value as PriceRange)}
                      className="w-full appearance-none bg-slate-900 border border-slate-700 text-white rounded-lg py-2 px-3 focus:ring-2 focus:ring-indigo-500 outline-none text-sm"
                    >
                      <option value="all">Qualsiasi prezzo</option>
                      <option value="free">Gratis</option>
                      <option value="under-30">Meno di €30</option>
                      <option value="30-60">€30 - €60</option>
                      <option value="over-60">Più di €60</option>
                    </select>
                    <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" size={14} />
                  </div>
                </div>
              </div>

              {/* Quick Sort Actions within filter area */}
              <div className="flex justify-between items-center border-t border-slate-700/50 pt-3">
                <div className="flex gap-2">
                   <button 
                    onClick={() => toggleSort('date')}
                    className={`flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                      sortField === 'date' ? 'bg-indigo-600/20 text-indigo-300 border border-indigo-500/30' : 'text-slate-400 hover:text-white'
                    }`}
                  >
                    <Calendar size={12} /> Data {sortField === 'date' && (sortOrder === 'asc' ? '↑' : '↓')}
                  </button>
                  <button 
                    onClick={() => toggleSort('cost')}
                    className={`flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                      sortField === 'cost' ? 'bg-indigo-600/20 text-indigo-300 border border-indigo-500/30' : 'text-slate-400 hover:text-white'
                    }`}
                  >
                    <Tag size={12} /> Costo {sortField === 'cost' && (sortOrder === 'asc' ? '↑' : '↓')}
                  </button>
                </div>
                <button onClick={clearFilters} className="text-xs text-slate-500 hover:text-white underline decoration-slate-600 underline-offset-2">
                  Reset Filtri
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Results List - Card Layout */}
      <div className="space-y-4">
        {filteredAndSortedConcerts.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-slate-500 animate-in fade-in zoom-in duration-500">
            <div className="w-20 h-20 bg-slate-800/50 rounded-full flex items-center justify-center mb-4">
              <Mic2 size={40} className="text-slate-600" />
            </div>
            <p className="text-lg font-medium">Nessun concerto trovato.</p>
            <p className="text-sm">Prova a cambiare i filtri.</p>
            <button onClick={clearFilters} className="mt-4 px-4 py-2 bg-indigo-600 text-white rounded-lg text-sm hover:bg-indigo-500 transition-colors">
              Mostra tutti
            </button>
          </div>
        ) : (
          filteredAndSortedConcerts.map((concert, index) => {
            const { day, month, year } = getDayAndMonth(concert.date);
            // Calculate delay for staggered animation based on index (max 10 items)
            const animationDelay = index < 10 ? `${index * 0.05}s` : '0s';

            return (
              <div 
                key={concert.id}
                className="animate-card group relative bg-slate-800 rounded-2xl overflow-hidden shadow-lg hover:shadow-2xl hover:shadow-indigo-900/20 transition-all duration-300 border border-slate-700/50 hover:border-indigo-500/30 hover:scale-[1.01]"
                style={{ animationDelay }}
              >
                {/* Background Decoration */}
                <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-600/5 rounded-full blur-3xl -mr-10 -mt-10 pointer-events-none"></div>

                <div className="flex flex-col sm:flex-row">

                  {/* Left: Date Ticket Stub */}
                  <div className="sm:w-24 bg-slate-900/50 border-b sm:border-b-0 sm:border-r border-slate-700/50 flex sm:flex-col items-center justify-between sm:justify-center p-3 sm:p-0 gap-1">
                    <div className="flex items-center sm:flex-col gap-2 sm:gap-0">
                      <span className="text-2xl sm:text-3xl font-black text-white">{day}</span>
                      <span className="text-sm font-bold text-indigo-400 uppercase tracking-widest">{month}</span>
                    </div>
                    <span className="text-xs font-medium text-slate-500 sm:mt-1">{year}</span>

                    {/* Visual notches for ticket effect */}
                    <div className="hidden sm:block absolute -right-1.5 top-0 w-3 h-3 bg-slate-900 rounded-full"></div>
                    <div className="hidden sm:block absolute -right-1.5 bottom-0 w-3 h-3 bg-slate-900 rounded-full"></div>
                  </div>

                  {/* Main Content */}
                  <div className="flex-1 p-4 flex flex-col justify-between gap-4">
                    <div className="flex justify-between items-start">
                      <div>
                        {/* Event Type Pill */}
                        <div className="inline-block px-2 py-0.5 rounded-md bg-slate-700/50 border border-slate-600/50 text-[10px] font-bold uppercase text-slate-300 tracking-wider mb-2">
                          {concert.event}
                        </div>
                        <h3 className="text-xl font-bold text-white leading-tight group-hover:text-indigo-300 transition-colors">
                          {concert.band}
                        </h3>
                        <div className="flex items-center gap-2 mt-2 text-sm text-slate-400">
                          <MapPin size={14} className="text-slate-500" />
                          <span>{concert.city}</span>
                        </div>
                      </div>

                      {/* Price Tag */}
                      <div className="text-right">
                        <div className={`font-bold text-lg ${concert.cost === 0 ? 'text-green-400' : 'text-white'}`}>
                          {concert.cost === 0 ? 'Free' : `€${concert.cost.toFixed(2)}`}
                        </div>
                        <div className="text-xs text-slate-500 mt-1">
                          {concert.artists > 1 ? `${concert.artists} artisti` : '1 artista'}
                        </div>
                      </div>
                    </div>

                    {/* Actions (Visible on hover on desktop, always there but subtle on mobile) */}
                    <div className="flex justify-end gap-2 pt-2 border-t border-slate-700/30 opacity-100 sm:opacity-0 sm:group-hover:opacity-100 transition-opacity duration-200">
                       <button 
                        onClick={(e) => { e.stopPropagation(); onEdit(concert); }}
                        className="flex items-center gap-1 px-3 py-1.5 bg-slate-700 hover:bg-indigo-600 text-white text-xs font-medium rounded-lg transition-colors"
                      >
                        <Edit2 size={12} /> Modifica
                      </button>
                      <button 
                        onClick={(e) => {
                          e.stopPropagation();
                          if (window.confirm('Sei sicuro di voler eliminare questo concerto?')) {
                            onDelete(concert.id);
                          }
                        }}
                        className="flex items-center gap-1 px-3 py-1.5 bg-slate-700 hover:bg-red-500 text-white text-xs font-medium rounded-lg transition-colors"
                      >
                        <Trash2 size={12} /> Elimina
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

import React from 'react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell, CartesianGrid } from 'recharts';
import { Concert } from '../types';
import { TrendingUp, DollarSign, Calendar, Music, Crown } from 'lucide-react';

interface StatisticsProps {
  concerts: Concert[];
}

export const Statistics: React.FC<StatisticsProps> = ({ concerts }) => {
  // 1. Calculate Summary Stats
  const totalSpent = concerts.reduce((acc, c) => acc + c.cost, 0);
  const totalConcerts = concerts.length;
  const totalArtists = concerts.reduce((acc, c) => acc + c.artists, 0);

  // 2. Prepare Chart Data (Spend per Year)
  const years = Array.from(new Set(concerts.map(c => c.year))).sort((a, b) => a - b);
  const dataByYear = years.map(year => {
    const yearlyConcerts = concerts.filter(c => c.year === year);
    return {
      year,
      spent: yearlyConcerts.reduce((acc, c) => acc + c.cost, 0),
      count: yearlyConcerts.length
    };
  });

  // 3. Top Artists Logic
  const artistCounts: Record<string, number> = {};
  concerts.forEach(c => {
    // Split by comma, clean whitespace, normalize case
    const artists = c.band.split(',').map(s => s.trim());
    artists.forEach(artist => {
      const name = artist; 
      artistCounts[name] = (artistCounts[name] || 0) + 1;
    });
  });

  const topArtists = Object.entries(artistCounts)
    .sort(([, a], [, b]) => b - a)
    .slice(0, 5); // Top 5

  return (
    <div className="space-y-8 pb-28">

      {/* KPI Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 animate-card" style={{ animationDelay: '0s' }}>
        <div className="glass-panel p-5 rounded-2xl relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
            <DollarSign size={40} />
          </div>
          <div className="text-xs font-bold uppercase tracking-widest text-indigo-400 mb-1">Totale Speso</div>
          <div className="text-3xl font-black text-white tracking-tight">€{totalSpent.toFixed(0)}</div>
          <div className="text-[10px] text-slate-500 mt-1">Costo totale biglietti</div>
        </div>

        <div className="glass-panel p-5 rounded-2xl relative overflow-hidden group">
           <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
            <Calendar size={40} />
          </div>
          <div className="text-xs font-bold uppercase tracking-widest text-purple-400 mb-1">Eventi</div>
          <div className="text-3xl font-black text-white tracking-tight">{totalConcerts}</div>
          <div className="text-[10px] text-slate-500 mt-1">Totale concerti visti</div>
        </div>

        <div className="glass-panel p-5 rounded-2xl relative overflow-hidden group">
           <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
            <Music size={40} />
          </div>
          <div className="text-xs font-bold uppercase tracking-widest text-pink-400 mb-1">Artisti</div>
          <div className="text-3xl font-black text-white tracking-tight">{totalArtists}</div>
          <div className="text-[10px] text-slate-500 mt-1">Band e cantanti unici</div>
        </div>

        <div className="glass-panel p-5 rounded-2xl relative overflow-hidden group">
           <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
            <TrendingUp size={40} />
          </div>
          <div className="text-xs font-bold uppercase tracking-widest text-emerald-400 mb-1">Media</div>
          <div className="text-3xl font-black text-white tracking-tight">€{(totalSpent / totalConcerts || 0).toFixed(0)}</div>
          <div className="text-[10px] text-slate-500 mt-1">Per evento</div>
        </div>
      </div>

      {/* Charts Row */}
      <div className="grid md:grid-cols-2 gap-6">

        {/* Money per Year */}
        <div className="glass-panel rounded-3xl p-6 animate-card" style={{ animationDelay: '0.1s' }}>
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold text-white">Spesa annuale</h3>
            <div className="text-xs text-slate-400 bg-slate-800 px-2 py-1 rounded">EUR (€)</div>
          </div>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={dataByYear}>
                <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} opacity={0.5} />
                <XAxis 
                  dataKey="year" 
                  stroke="#94a3b8" 
                  tick={{fontSize: 12}} 
                  axisLine={false} 
                  tickLine={false} 
                  dy={10} 
                />
                <YAxis 
                  stroke="#94a3b8" 
                  tick={{fontSize: 12}} 
                  tickFormatter={(val) => `€${val}`} 
                  axisLine={false} 
                  tickLine={false} 
                  dx={-10}
                />
                <Tooltip 
                  cursor={{ fill: '#334155', opacity: 0.2 }}
                  contentStyle={{ 
                    backgroundColor: '#0f172a', 
                    borderColor: '#334155', 
                    color: '#f8fafc',
                    borderRadius: '8px',
                    boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.5)'
                  }}
                  itemStyle={{ color: '#818cf8' }}
                  formatter={(value: number) => [`€${value.toFixed(2)}`, 'Spesa']}
                />
                <Bar dataKey="spent" radius={[6, 6, 0, 0]} animationDuration={1500}>
                  {dataByYear.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill="url(#colorGradient)" />
                  ))}
                </Bar>
                <defs>
                  <linearGradient id="colorGradient" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#6366f1" stopOpacity={1}/>
                    <stop offset="95%" stopColor="#8b5cf6" stopOpacity={0.6}/>
                  </linearGradient>
                </defs>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Top Artists List */}
        <div className="glass-panel rounded-3xl p-6 animate-card" style={{ animationDelay: '0.2s' }}>
          <div className="flex items-center justify-between mb-6">
             <h3 className="text-lg font-bold text-white">Top 5 Artisti</h3>
             <Crown size={18} className="text-yellow-500" />
          </div>

          <div className="space-y-4">
            {topArtists.map(([artist, count], idx) => (
              <div key={idx} className="flex items-center justify-between p-3 rounded-xl bg-slate-800/40 border border-slate-700/30 hover:bg-slate-800 transition-colors group">
                <div className="flex items-center gap-4">
                  <div className={`
                    flex items-center justify-center w-10 h-10 rounded-xl font-bold text-sm shadow-inner
                    ${idx === 0 ? 'bg-gradient-to-br from-yellow-400 to-orange-500 text-slate-900' : 
                      idx === 1 ? 'bg-gradient-to-br from-slate-300 to-slate-400 text-slate-900' :
                      idx === 2 ? 'bg-gradient-to-br from-orange-300 to-orange-400 text-slate-900' :
                      'bg-slate-700 text-slate-300'}
                  `}>
                    {idx + 1}
                  </div>
                  <div>
                    <div className="font-semibold text-white group-hover:text-indigo-300 transition-colors">{artist}</div>
                    <div className="w-full bg-slate-700 h-1.5 rounded-full mt-1.5 w-24 overflow-hidden">
                       <div 
                        className="h-full bg-indigo-500 rounded-full" 
                        style={{ width: `${(count / topArtists[0][1]) * 100}%` }}
                       ></div>
                    </div>
                  </div>
                </div>
                <div className="text-right">
                  <div className="text-lg font-bold text-white">{count}</div>
                  <div className="text-[10px] text-slate-500 uppercase">Presenze</div>
                </div>
              </div>
            ))}
          </div>
        </div>

      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useConcerts } from './hooks/useConcerts';
import { Navbar } from './components/Navbar';
import { ConcertTable } from './components/ConcertTable';
import { Statistics } from './components/Statistics';
import { ConcertForm } from './components/ConcertForm';
import { Concert } from './types';

function App() {
  const { concerts, addConcert, updateConcert, deleteConcert } = useConcerts();
  const [view, setView] = useState<'list' | 'stats'>('list');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingConcert, setEditingConcert] = useState<Concert | undefined>(undefined);

  const handleAddClick = () => {
    setEditingConcert(undefined);
    setIsFormOpen(true);
  };

  const handleEditClick = (concert: Concert) => {
    setEditingConcert(concert);
    setIsFormOpen(true);
  };

  const handleFormSubmit = (data: Omit<Concert, 'id'>) => {
    if (editingConcert) {
      updateConcert(editingConcert.id, data);
    } else {
      addConcert(data);
    }
  };

  return (
    <div className="min-h-screen bg-slate-900 text-slate-50 selection:bg-indigo-500 selection:text-white pb-20">
      {/* Changed max-w-3xl to max-w-7xl for full width experience */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-8">

        {/* Header */}
        <header className="mb-8 flex flex-col md:flex-row md:items-end justify-between gap-4">
          <div>
            <h1 className="text-4xl md:text-5xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 via-purple-400 to-pink-400 animate-in fade-in slide-in-from-left-4 duration-700">
              Concert Tracker
            </h1>
            <p className="text-slate-400 text-base mt-2 max-w-xl">
              Il tuo diario musicale digitale. Hai partecipato a <strong className="text-white">{concerts.length}</strong> eventi finora.
            </p>
          </div>
        </header>

        {/* Main Content Area */}
        <main className="w-full">
          {view === 'list' ? (
            <ConcertTable 
              concerts={concerts} 
              onEdit={handleEditClick} 
              onDelete={deleteConcert} 
            />
          ) : (
            <Statistics concerts={concerts} />
          )}
        </main>
      </div>

      {/* Floating UI Elements */}
      <ConcertForm
        isOpen={isFormOpen}
        onClose={() => setIsFormOpen(false)}
        onSubmit={handleFormSubmit}
        initialData={editingConcert}
      />

      <Navbar 
        currentView={view} 
        setView={setView} 
        onAddClick={handleAddClick} 
      />
    </div>
  );
}

