                    <h3 className="text-xl font-bold text-white leading-tight group-hover:text-indigo-300 transition-colors line-clamp-2" title={concert.band}>
                      {concert.band}
                    </h3>
                    <div className="flex items-start gap-2 mt-3 text-sm text-slate-400">
                      <MapPin size={16} className="text-slate-500 mt-0.5 shrink-0" />
                      <span className="line-clamp-1">{concert.city}</span>
                    </div>
                  </div>

                  <div className="flex items-center justify-between mt-2 pt-4 border-t border-slate-700/30">
                     <span className="text-xs text-slate-500 flex items-center gap-1">
                       <Users size={12} />
                       {concert.artists > 1 ? `${concert.artists} artisti` : '1 artista'}
                     </span>

                     <div className="flex gap-1 opacity-100 sm:opacity-0 sm:group-hover:opacity-100 transition-opacity duration-200">
                        <button 
                          onClick={(e) => { e.stopPropagation(); onEdit(concert); }}
                          className="p-2 hover:bg-indigo-600/20 text-slate-400 hover:text-indigo-400 rounded-lg transition-colors"
                        >
                          <Edit2 size={16} />
                        </button>
                        <button 
                          onClick={(e) => {
                            e.stopPropagation();
                            if (window.confirm('Sei sicuro di voler eliminare questo concerto?')) {
                              onDelete(concert.id);
                            }
                          }}
                          className="p-2 hover:bg-red-500/20 text-slate-400 hover:text-red-400 rounded-lg transition-colors"
                        >
                          <Trash2 size={16} />
                        </button>
                     </div>
                  </div>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

import { useState, useEffect } from 'react';
import { Concert } from '../types';
import { INITIAL_CONCERTS } from '../constants';

export const useConcerts = () => {
  // Use lazy initialization to load and merge data synchronously on mount.
  // This prevents the "flash" of empty data and race conditions with localStorage.
  const [concerts, setConcerts] = useState<Concert[]>(() => {
    try {
      const savedJSON = localStorage.getItem('concerts_v2');
      const savedData: Concert[] = savedJSON ? JSON.parse(savedJSON) : [];

      // 1. Identify User-Added Concerts (UUIDs)
      // We assume IDs starting with 'init-' are from constants.ts, others are manual additions.
      const userAddedConcerts = savedData.filter(c => !c.id.startsWith('init-'));

      // 2. Smart Merge Strategy:
      // Always take the fresh INITIAL_CONCERTS from code (to reflect code changes/fixes).
      // Append the User-Added concerts from storage.
      // This ensures that if you edit constants.ts, you see the changes, but you don't lose your manual entries.
      return [...INITIAL_CONCERTS, ...userAddedConcerts];

    } catch (e) {
      console.error("Failed to load concerts", e);
      return INITIAL_CONCERTS;
    }
  });

  // Save to local storage whenever concerts change
  useEffect(() => {
    localStorage.setItem('concerts_v2', JSON.stringify(concerts));
  }, [concerts]);

  const addConcert = (concert: Omit<Concert, 'id'>) => {
    const newConcert = {
      ...concert,
      id: crypto.randomUUID(), // Ensure manual entries have UUIDs, not 'init-' IDs
    };
    setConcerts(prev => [...prev, newConcert]);
  };

  const updateConcert = (id: string, updated: Partial<Concert>) => {
    setConcerts(prev => prev.map(c => (c.id === id ? { ...c, ...updated } : c)));
  };

  const deleteConcert = (id: string) => {
    setConcerts(prev => prev.filter(c => c.id !== id));
  };

  return { concerts, addConcert, updateConcert, deleteConcert };
};

import React, { useState, useEffect, useRef } from 'react';
import { X, Calendar, MapPin, Ticket, Music2, PartyPopper, Camera, Loader2, Sparkles, FileText, ImageIcon, Mail, FileType } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";
import { Concert } from '../types';

interface ConcertFormProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: Omit<Concert, 'id'>) => void;
  initialData?: Concert;
}

export const ConcertForm: React.FC<ConcertFormProps> = ({ isOpen, onClose, onSubmit, initialData }) => {
  const [formData, setFormData] = useState({
    band: '',
    date: '',
    city: '',
    event: '',
    cost: 0,
  });

  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisMode, setAnalysisMode] = useState<'image' | 'text'>('image');
  const [emailText, setEmailText] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (initialData) {
      setFormData({
        band: initialData.band,
        date: initialData.date,
        city: initialData.city,
        event: initialData.event,
        cost: initialData.cost,
      });
    } else {
      setFormData({
        band: '',
        date: new Date().toISOString().split('T')[0],
        city: '',
        event: 'Concerto',
        cost: 0,
      });
      setEmailText(''); // Reset text on new open
    }
  }, [initialData, isOpen]);

  // Shared helper to update form from JSON data
  const updateFormFromData = (data: any) => {
    setFormData(prev => ({
      ...prev,
      band: data.band || prev.band,
      date: data.date || prev.date,
      city: data.city || prev.city,
      event: data.event || prev.event,
      cost: typeof data.cost === 'number' ? data.cost : prev.cost
    }));
  };

  const openGmailSearch = () => {
    // Opens Gmail searching for common ticket keywords
    const query = encodeURIComponent("subject:(biglietti OR ticket OR ordine OR conferma OR order OR confirmation)");
    window.open(`https://mail.google.com/mail/u/0/#search/${query}`, '_blank');
  };

  const handleTextAnalysis = async () => {
    if (!emailText.trim()) return;
    setIsAnalyzing(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: {
          parts: [
            {
              text: `Analyze the following text which is likely an email confirmation for a concert ticket or an event description. 
              Extract the details in JSON format using the schema provided.

              TEXT TO ANALYZE:
              "${emailText}"

              Instructions:
              - 'band': Main artist(s).
              - 'date': YYYY-MM-DD.
              - 'city': City name.
              - 'event': Event name.
              - 'cost': Total cost found in the text (number only).`
            }
          ]
        },
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
             type: Type.OBJECT,
             properties: {
               band: { type: Type.STRING },
               date: { type: Type.STRING },
               city: { type: Type.STRING },
               event: { type: Type.STRING },
               cost: { type: Type.NUMBER }
             }
          }
        }
      });

      const text = response.text;
      if (text) {
        updateFormFromData(JSON.parse(text));
      }
    } catch (error) {
      console.error("Error analyzing text:", error);
      alert("Errore durante l'analisi del testo. Riprova.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Basic validation for image or PDF
    if (!file.type.startsWith('image/') && file.type !== 'application/pdf') {
      alert("Per favore carica un'immagine o un file PDF.");
      return;
    }

    setIsAnalyzing(true);

    try {
      // 1. Convert to Base64
      const base64Data = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => {
          const result = reader.result as string;
          // Extract base64 part
          const base64Content = result.split(',')[1];
          resolve(base64Content);
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });

      // 2. Call Gemini
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: {
          parts: [
            {
              inlineData: {
                mimeType: file.type,
                data: base64Data
              }
            },
            {
              text: `Analyze this file (image or PDF document) of a concert ticket, receipt, or poster.

              CONTEXT FROM FILENAME: "${file.name}" (Use this to infer band name, date, or city if the information is missing or unclear in the image itself).

              Extract the following details in JSON format:
              - 'band': The name of the main artist or bands (comma separated if multiple).
              - 'date': The date of the event in YYYY-MM-DD format.
              - 'city': The city where the event takes place.
              - 'event': The name of the tour or event type (e.g., 'Concerto', 'Festival', 'Tour Name').
              - 'cost': The total price found (number only). If free or not found, use 0.`
            }
          ]
        },
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
             type: Type.OBJECT,
             properties: {
               band: { type: Type.STRING },
               date: { type: Type.STRING },
               city: { type: Type.STRING },
               event: { type: Type.STRING },
               cost: { type: Type.NUMBER }
             }
          }
        }
      });

      // 3. Parse and Populate
      const text = response.text;
      if (text) {
        updateFormFromData(JSON.parse(text));
      }

    } catch (error) {
      console.error("Error analyzing file:", error);
      alert("Impossibile analizzare il file. Assicurati che non sia protetto da password.");
    } finally {
      setIsAnalyzing(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const dateObj = new Date(formData.date);
    const year = dateObj.getFullYear();

    // Auto-calculate artists count based on commas
    const artistCount = formData.band
      .split(',')
      .map(s => s.trim())
      .filter(s => s.length > 0)
      .length;

    const finalArtists = artistCount > 0 ? artistCount : 1;

    // Normalize Event Name for PPMP
    let finalEvent = formData.event;
    const lowerEvent = finalEvent.toLowerCase().trim();
    if (lowerEvent === 'ppmp' || lowerEvent === 'pop punk mosh party') {
       finalEvent = 'PPMP - Pop Punk Mosh Party';
    }

    onSubmit({
      ...formData,
      event: finalEvent,
      artists: finalArtists,
      year,
    });
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
      <div className="bg-slate-900 border border-slate-700 w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-300 max-h-[90vh] overflow-y-auto">
        <div className="p-6 border-b border-slate-800 flex justify-between items-center bg-slate-800/50 sticky top-0 backdrop-blur-sm z-10">
          <div>
            <h2 className="text-2xl font-bold text-white">
              {initialData ? 'Modifica Evento' : 'Nuovo Evento'}
            </h2>
            <p className="text-xs text-slate-400 mt-1">
              Inserisci i dettagli del concerto.
            </p>
          </div>
          <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-800 text-slate-400 hover:text-white transition-colors">
            <X size={24} />
          </button>
        </div>

        <div className="p-6 space-y-6">

          {/* AI Import Section */}
          {!initialData && (
             <div className="bg-slate-800/50 p-4 rounded-xl border border-slate-700/50 space-y-4">
               <div className="flex items-center justify-between">
                  <h3 className="text-sm font-bold text-indigo-300 flex items-center gap-2">
                    <Sparkles size={14} /> Importazione Automatica (AI)
                  </h3>

                  {/* Mode Toggles */}
                  <div className="flex bg-slate-900 rounded-lg p-1 border border-slate-700">
                    <button 
                      onClick={() => setAnalysisMode('image')}
                      className={`p-1.5 rounded-md transition-all ${analysisMode === 'image' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                      title="Carica File (IMG/PDF)"
                    >
                      <FileType size={16} />
                    </button>
                    <button 
                      onClick={() => setAnalysisMode('text')}
                      className={`p-1.5 rounded-md transition-all ${analysisMode === 'text' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                      title="Incolla Testo Email"
                    >
                      <FileText size={16} />
                    </button>
                  </div>
               </div>

               {analysisMode === 'image' ? (
                 <div className="flex flex-col sm:flex-row items-center justify-between gap-4 animate-in fade-in duration-300">
                   <p className="text-[10px] text-slate-400">
                     Carica un biglietto PDF, uno screenshot o una locandina.
                   </p>
                   <input 
                     type="file" 
                     ref={fileInputRef} 
                     onChange={handleFileChange} 
                     accept="image/*,application/pdf" 
                     className="hidden" 
                   />
                   <button
                     type="button"
                     onClick={() => fileInputRef.current?.click()}
                     disabled={isAnalyzing}
                     className="w-full sm:w-auto flex items-center justify-center gap-2 bg-slate-700 hover:bg-slate-600 text-white text-xs font-bold py-2.5 px-4 rounded-lg transition-colors shadow-sm whitespace-nowrap"
                   >
                     {isAnalyzing ? (
                       <><Loader2 size={16} className="animate-spin" /> Analisi...</>
                     ) : (
                       <><FileType size={16} /> Carica File</>
                     )}
                   </button>
                 </div>
               ) : (
                 <div className="space-y-3 animate-in fade-in duration-300">
                   <div className="flex justify-between items-center">
                     <p className="text-[10px] text-slate-400">
                       Incolla qui il testo della mail.
                     </p>
                     <button 
                        type="button"
                        onClick={openGmailSearch}
                        className="text-[10px] text-indigo-400 hover:text-indigo-300 flex items-center gap-1 font-semibold transition-colors"
                     >
                        <Mail size={12} /> Cerca su Gmail
                     </button>
                   </div>
                   <textarea
                     value={emailText}
                     onChange={(e) => setEmailText(e.target.value)}
                     placeholder="Es: 'Ciao, ecco i tuoi biglietti per il concerto dei Linkin Park a Milano il 24 Giugno 2025. Totale pagato: €85.90...'"
                     className="w-full h-24 bg-slate-900/80 border border-slate-700 rounded-lg p-3 text-xs text-white placeholder:text-slate-600 focus:ring-1 focus:ring-indigo-500 outline-none resize-none"
                   />
                   <button
                     type="button"
                     onClick={handleTextAnalysis}
                     disabled={isAnalyzing || !emailText.trim()}
                     className="w-full flex items-center justify-center gap-2 bg-slate-700 hover:bg-slate-600 disabled:opacity-50 text-white text-xs font-bold py-2.5 px-4 rounded-lg transition-colors shadow-sm"
                   >
                     {isAnalyzing ? (
                       <><Loader2 size={16} className="animate-spin" /> Elaborazione...</>
                     ) : (
                       <><Sparkles size={16} /> Estrai Dati da Testo</>
                     )}
                   </button>
                 </div>
               )}
             </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">

            <div className="space-y-2">
              <label className="text-xs uppercase font-bold text-indigo-400 flex items-center gap-2">
                <Music2 size={16} /> Artisti (Separati da virgola)
              </label>
              <input
                required
                type="text"
                value={formData.band}
                onChange={(e) => setFormData({ ...formData, band: e.target.value })}
                className="w-full bg-slate-950 border border-slate-700 rounded-xl p-4 text-lg text-white focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all placeholder:text-slate-600"
                placeholder="Es. Simple Plan, Sum 41, Offspring"
              />
            </div>

            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-xs uppercase font-bold text-slate-400 flex items-center gap-2">
                  <Calendar size={16} /> Data
                </label>
                <input
                  required
                  type="date"
                  value={formData.date}
                  onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-white focus:ring-2 focus:ring-indigo-500 outline-none"
                />
              </div>
               <div className="space-y-2">
                <label className="text-xs uppercase font-bold text-slate-400 flex items-center gap-2">
                  <Ticket size={16} /> Costo Totale (€)
                </label>
                <input
                  required
                  type="number"
                  step="0.01"
                  min="0"
                  value={formData.cost}
                  onChange={(e) => setFormData({ ...formData, cost: parseFloat(e.target.value) })}
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-white focus:ring-2 focus:ring-indigo-500 outline-none"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs uppercase font-bold text-slate-400 flex items-center gap-2">
                <MapPin size={16} /> Città / Luogo
              </label>
              <input
                required
                type="text"
                value={formData.city}
                onChange={(e) => setFormData({ ...formData, city: e.target.value })}
                className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-white focus:ring-2 focus:ring-indigo-500 outline-none"
                placeholder="Es. Milano, Fabrique"
              />
            </div>

            <div className="space-y-2">
              <label className="text-xs uppercase font-bold text-slate-400 flex items-center gap-2">
                <PartyPopper size={16} /> Nome Evento / Tour
