import { useState, useEffect } from 'react';
import { Concert } from '../types';
import { INITIAL_CONCERTS } from '../constants';

export const useConcerts = () => {
  // Helper to generate IDs safely (fallback for browsers where crypto.randomUUID might be restricted)
  const generateId = () => {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) {
      return crypto.randomUUID();
    }
    return `manual-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
  };

  const [concerts, setConcerts] = useState<Concert[]>(() => {
    try {
      // 1. Check if we have saved data in the browser
      const savedJSON = localStorage.getItem('concerts_v2');

      if (savedJSON) {
        // If data exists, WE USE IT as the source of truth.
        // This ensures that if you deleted or edited an initial concert, 
        // those changes are respected and not overwritten by the code file.
        return JSON.parse(savedJSON);
      }

      // 2. If it's the VERY FIRST time opening the app (no data saved),
      // we seed the database with the list from constants.ts
      return INITIAL_CONCERTS;

    } catch (e) {
      console.error("Failed to load concerts", e);
      return INITIAL_CONCERTS;
    }
  });

  // Save to local storage whenever the list changes (add, edit, delete)
  useEffect(() => {
    localStorage.setItem('concerts_v2', JSON.stringify(concerts));
  }, [concerts]);

  const addConcert = (concert: Omit<Concert, 'id'>) => {
    const newConcert = {
      ...concert,
      id: generateId(), 
    };
    setConcerts(prev => [newConcert, ...prev]); // Add to top of list
  };

  const updateConcert = (id: string, updated: Partial<Concert>) => {
    setConcerts(prev => prev.map(c => (c.id === id ? { ...c, ...updated } : c)));
  };

  const deleteConcert = (id: string) => {
    setConcerts(prev => prev.filter(c => c.id !== id));
  };

  return { concerts, addConcert, updateConcert, deleteConcert };
};

