import { useState, useEffect } from 'react';
import { Concert } from '../types';
import { supabase } from '../supabaseClient';
import { INITIAL_CONCERTS } from '../constants';

export const useConcerts = () => {
  const [concerts, setConcerts] = useState<Concert[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Fetch concerts from Supabase
  const fetchConcerts = async () => {
    try {
      setLoading(true);
      const { data, error } = await supabase
        .from('concerts')
        .select('*')
        .order('date', { ascending: false });

      if (error) throw error;

      // SEEDING LOGIC:
      // If the database is empty (first run), we populate it with the static JSON file.
      // This ensures your historic data is uploaded to the cloud automatically.
      if (!data || data.length === 0) {
        console.log("Database empty. Seeding initial data...");
        await seedInitialData();
      } else {
        setConcerts(data);
      }
    } catch (err: any) {
      console.error('Error fetching concerts:', err.message);
      setError(err.message);
      // Fallback: load from constants if DB connection fails (e.g. table doesn't exist yet)
      setConcerts(INITIAL_CONCERTS);
    } finally {
      setLoading(false);
    }
  };

  const seedInitialData = async () => {
    try {
      // We strip the IDs from INITIAL_CONCERTS to let Supabase generate proper UUIDs
      const dataToInsert = INITIAL_CONCERTS.map(({ id, ...rest }) => rest);

      const { data, error } = await supabase
        .from('concerts')
        .insert(dataToInsert)
        .select()
        .order('date', { ascending: false });

      if (error) throw error;
      if (data) setConcerts(data);

    } catch (err) {
      console.error("Error seeding data:", err);
      // If seeding fails, we just show local data without crashing
      setConcerts(INITIAL_CONCERTS); 
    }
  };

  useEffect(() => {
    fetchConcerts();
  }, []);

  const addConcert = async (concert: Omit<Concert, 'id'>) => {
    try {
      // Insert into Supabase
      const { data, error } = await supabase
        .from('concerts')
        .insert([concert])
        .select()
        .single();

      if (error) throw error;
      if (data) {
        setConcerts(prev => [data, ...prev]);
      }
    } catch (err) {
      alert("Errore nell'aggiunta del concerto su Supabase. Controlla la console.");
      console.error(err);
    }
  };

  const updateConcert = async (id: string, updated: Partial<Concert>) => {
    try {
      // Remove any fields that shouldn't be updated or might cause issues
      const { id: _, ...cleanUpdates } = updated as any;

      const { error } = await supabase
        .from('concerts')
        .update(cleanUpdates)
        .eq('id', id);

      if (error) throw error;

      // Update local state
      setConcerts(prev => prev.map(c => (c.id === id ? { ...c, ...updated } : c)));
    } catch (err) {
      alert("Errore nell'aggiornamento su Supabase.");
      console.error(err);
    }
  };

  const deleteConcert = async (id: string) => {
    try {
      const { error } = await supabase
        .from('concerts')
        .delete()
        .eq('id', id);

      if (error) throw error;

      setConcerts(prev => prev.filter(c => c.id !== id));
    } catch (err) {
      alert("Errore nell'eliminazione su Supabase.");
      console.error(err);
    }
  };

  return { concerts, loading, error, addConcert, updateConcert, deleteConcert };
};

import React, { useState, useEffect, useRef } from 'react';
import { X, Calendar, MapPin, Ticket, Music2, PartyPopper, Camera, Loader2, Sparkles, FileText, ImageIcon, Mail, FileType, Type, MapPinned } from 'lucide-react';
import { GoogleGenAI, Type as GenAiType } from "@google/genai";
import { Concert } from '../types';

interface ConcertFormProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: Omit<Concert, 'id'>) => void;
  initialData?: Concert;
}

const SPECIAL_UPPERCASE = ['WEL', 'WET', 'POE', 'PPMP', 'DJ', 'PR'];

export const ConcertForm: React.FC<ConcertFormProps> = ({ isOpen, onClose, onSubmit, initialData }) => {
  const [formData, setFormData] = useState({
    band: '',
    date: '',
    city: '',
    event: '',
    cost: 0,
  });

  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isLocating, setIsLocating] = useState(false);
  const [analysisMode, setAnalysisMode] = useState<'image' | 'text'>('image');
  const [emailText, setEmailText] = useState('');
  const [autoFormat, setAutoFormat] = useState(true); // Default to auto-format
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (initialData) {
      setFormData({
        band: initialData.band,
        date: initialData.date,
        city: initialData.city,
        event: initialData.event,
        cost: initialData.cost,
      });
    } else {
      setFormData({
        band: '',
        date: new Date().toISOString().split('T')[0],
        city: '',
        event: 'Concerto',
        cost: 0,
      });
      setEmailText('');
      setAutoFormat(true);
    }
  }, [initialData, isOpen]);

  // Helper to format a single string (Title Case with exceptions)
  const formatString = (str: string): string => {
    if (!str) return '';
    return str.split(' ').map(word => {
      // Remove punctuation for the check (e.g., "WEL," -> "WEL")
      const cleanWord = word.replace(/[^a-zA-Z0-9]/g, '').toUpperCase();

      // If it's a special word, return it fully uppercase (preserving original punctuation if needed is tricky, 
      // but simple replacement works for most cases. Let's rebuild the word carefully).
      if (SPECIAL_UPPERCASE.includes(cleanWord)) {
        return word.toUpperCase();
      }

      // Standard Title Case: First letter upper, rest lower
      return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
    }).join(' ');
  };

  // Helper specifically for comma-separated lists (like bands)
  const formatList = (str: string): string => {
    return str.split(',').map(part => formatString(part.trim())).join(', ');
  };

  const updateFormFromData = (data: any) => {
    setFormData(prev => ({
      ...prev,
      band: data.band || prev.band,
      date: data.date || prev.date,
      city: data.city || prev.city,
      event: data.event || prev.event,
      cost: typeof data.cost === 'number' ? data.cost : prev.cost
    }));
  };

  const openGmailSearch = () => {
    const query = encodeURIComponent("subject:(biglietti OR ticket OR ordine OR conferma OR order OR confirmation)");
    window.open(`https://mail.google.com/mail/u/0/#search/${query}`, '_blank');
  };

  const handleEnrichLocation = async () => {
    if (!formData.band || !formData.city) return;
    setIsLocating(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: {
          parts: [{
            text: `Identify the specific concert venue.
            Artist: ${formData.band}
            Date: ${formData.date}
            City: ${formData.city}
            Current Event Name: ${formData.event}

            Task: Return the specific venue name combined with the city.
            Format: "City, Venue Name" (e.g. "Milano, Fabrique" or "Parma, Parco Ducale").

            Rules:
            1. If the input City already contains the venue (e.g. "Milano, Fabrique"), return it as is.
            2. If you cannot find a specific venue for this date/artist in this city, return just the City.
            3. Prioritize famous venues (stadiums, clubs, parks).`
          }]
        },
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
            type: GenAiType.OBJECT,
            properties: {
              venue: { type: GenAiType.STRING }
            }
          }
        }
      });

      const result = JSON.parse(response.text || '{}');
      if (result.venue) {
        setFormData(prev => ({ ...prev, city: result.venue }));
      }
    } catch (e) {
      console.error("Error enriching location", e);
    } finally {
      setIsLocating(false);
    }
  };

  const handleTextAnalysis = async () => {
    if (!emailText.trim()) return;
    setIsAnalyzing(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: {
          parts: [
            {
              text: `Analyze the following text which is likely an email confirmation for a concert ticket or an event description. 
              Extract the details in JSON format using the schema provided.

              TEXT TO ANALYZE:
              "${emailText}"

              Instructions:
              - 'band': Main artist(s).
              - 'date': YYYY-MM-DD.
              - 'city': City name (Try to include venue if available, e.g. "Milano, Fabrique").
              - 'event': Event name.
              - 'cost': Total cost found in the text (number only).`
            }
          ]
        },
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
             type: GenAiType.OBJECT,
             properties: {
               band: { type: GenAiType.STRING },
               date: { type: GenAiType.STRING },
               city: { type: GenAiType.STRING },
               event: { type: GenAiType.STRING },
               cost: { type: GenAiType.NUMBER }
             }
          }
        }
      });

      const text = response.text;
      if (text) {
        updateFormFromData(JSON.parse(text));
      }
    } catch (error) {
      console.error("Error analyzing text:", error);
      alert("Errore durante l'analisi del testo. Riprova.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/') && file.type !== 'application/pdf') {
      alert("Per favore carica un'immagine o un file PDF.");
      return;
    }

    setIsAnalyzing(true);

    try {
      const base64Data = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => {
          const result = reader.result as string;
          const base64Content = result.split(',')[1];
          resolve(base64Content);
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: {
          parts: [
            {
              inlineData: {
                mimeType: file.type,
                data: base64Data
              }
            },
            {
              text: `Analyze this file (image or PDF document) of a concert ticket, receipt, or poster.
              CONTEXT FROM FILENAME: "${file.name}"
              Extract: band, date, city (include venue if visible), event, cost (number). JSON format.`
            }
          ]
        },
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
             type: GenAiType.OBJECT,
             properties: {
               band: { type: GenAiType.STRING },
               date: { type: GenAiType.STRING },
               city: { type: GenAiType.STRING },
               event: { type: GenAiType.STRING },
               cost: { type: GenAiType.NUMBER }
             }
          }
        }
      });

      const text = response.text;
      if (text) {
        updateFormFromData(JSON.parse(text));
      }

    } catch (error) {
      console.error("Error analyzing file:", error);
      alert("Impossibile analizzare il file.");
    } finally {
      setIsAnalyzing(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const dateObj = new Date(formData.date);
    const year = dateObj.getFullYear();

    // Auto-formatting logic
    let finalBand = formData.band;
    let finalCity = formData.city;
    let finalEvent = formData.event;

    if (autoFormat) {
      finalBand = formatList(formData.band);
      finalCity = formatString(formData.city);
      finalEvent = formatString(formData.event);
    }

    // Auto-calculate artists count based on commas
    const artistCount = finalBand
      .split(',')
      .map(s => s.trim())
      .filter(s => s.length > 0)
      .length;

    const finalArtists = artistCount > 0 ? artistCount : 1;

    // Normalize Event Name for PPMP (Specific logic override)
    const lowerEvent = finalEvent.toLowerCase().trim();
    if (lowerEvent === 'ppmp' || lowerEvent === 'pop punk mosh party') {
       finalEvent = 'PPMP - Pop Punk Mosh Party';
    }

    onSubmit({
      ...formData,
      band: finalBand,
      city: finalCity,
      event: finalEvent,
      artists: finalArtists,
      year,
    });
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
      <div className="bg-slate-900 border border-slate-700 w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-300 max-h-[90vh] overflow-y-auto">
        <div className="p-6 border-b border-slate-800 flex justify-between items-center bg-slate-800/50 sticky top-0 backdrop-blur-sm z-10">
          <div>
            <h2 className="text-2xl font-bold text-white">
              {initialData ? 'Modifica Evento' : 'Nuovo Evento'}
            </h2>
            <p className="text-xs text-slate-400 mt-1">
              Inserisci i dettagli del concerto.
            </p>
          </div>
          <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-800 text-slate-400 hover:text-white transition-colors">
            <X size={24} />
          </button>
        </div>

        <div className="p-6 space-y-6">

          {/* AI Import Section */}
          {!initialData && (
             <div className="bg-slate-800/50 p-4 rounded-xl border border-slate-700/50 space-y-4">
               <div className="flex items-center justify-between">
                  <h3 className="text-sm font-bold text-indigo-300 flex items-center gap-2">
                    <Sparkles size={14} /> Importazione Automatica (AI)
                  </h3>

                  <div className="flex bg-slate-900 rounded-lg p-1 border border-slate-700">
                    <button 
                      type="button"
                      onClick={() => setAnalysisMode('image')}
                      className={`p-1.5 rounded-md transition-all ${analysisMode === 'image' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                    >
                      <FileType size={16} />
                    </button>
                    <button 
                      type="button"
                      onClick={() => setAnalysisMode('text')}
                      className={`p-1.5 rounded-md transition-all ${analysisMode === 'text' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                    >
                      <FileText size={16} />
                    </button>
                  </div>
               </div>

               {analysisMode === 'image' ? (
                 <div className="flex flex-col sm:flex-row items-center justify-between gap-4 animate-in fade-in duration-300">
                   <p className="text-[10px] text-slate-400">
                     Carica un biglietto PDF, uno screenshot o una locandina.
                   </p>
                   <input 
                     type="file" 
                     ref={fileInputRef} 
                     onChange={handleFileChange} 
                     accept="image/*,application/pdf" 
                     className="hidden" 
                   />
                   <button
                     type="button"
                     onClick={() => fileInputRef.current?.click()}
                     disabled={isAnalyzing}
                     className="w-full sm:w-auto flex items-center justify-center gap-2 bg-slate-700 hover:bg-slate-600 text-white text-xs font-bold py-2.5 px-4 rounded-lg transition-colors shadow-sm whitespace-nowrap"
                   >
                     {isAnalyzing ? (
                       <><Loader2 size={16} className="animate-spin" /> Analisi...</>
                     ) : (
                       <><FileType size={16} /> Carica File</>
                     )}
                   </button>
                 </div>
               ) : (
                 <div className="space-y-3 animate-in fade-in duration-300">
                   <div className="flex justify-between items-center">
                     <p className="text-[10px] text-slate-400">
                       Incolla qui il testo della mail.
                     </p>
                     <button 
                        type="button"
                        onClick={openGmailSearch}
                        className="text-[10px] text-indigo-400 hover:text-indigo-300 flex items-center gap-1 font-semibold transition-colors"
                     >
                        <Mail size={12} /> Cerca su Gmail
                     </button>
                   </div>
                   <textarea
                     value={emailText}
                     onChange={(e) => setEmailText(e.target.value)}
                     placeholder="Incolla il testo qui..."
                     className="w-full h-24 bg-slate-900/80 border border-slate-700 rounded-lg p-3 text-xs text-white placeholder:text-slate-600 focus:ring-1 focus:ring-indigo-500 outline-none resize-none"
                   />
                   <button
                     type="button"
                     onClick={handleTextAnalysis}
                     disabled={isAnalyzing || !emailText.trim()}
                     className="w-full flex items-center justify-center gap-2 bg-slate-700 hover:bg-slate-600 disabled:opacity-50 text-white text-xs font-bold py-2.5 px-4 rounded-lg transition-colors shadow-sm"
                   >
                     {isAnalyzing ? (
                       <><Loader2 size={16} className="animate-spin" /> Elaborazione...</>
                     ) : (
                       <><Sparkles size={16} /> Estrai Dati</>
                     )}
                   </button>
                 </div>
               )}
             </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">

            <div className="space-y-2">
              <label className="text-xs uppercase font-bold text-indigo-400 flex items-center gap-2">
                <Music2 size={16} /> Artisti (Separati da virgola)
              </label>
              <input
                required
                type="text"
                value={formData.band}
                onChange={(e) => setFormData({ ...formData, band: e.target.value })}
                className="w-full bg-slate-950 border border-slate-700 rounded-xl p-4 text-lg text-white focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all placeholder:text-slate-600"
                placeholder="Es. Simple Plan, Sum 41"
              />
            </div>

            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-xs uppercase font-bold text-slate-400 flex items-center gap-2">
                  <Calendar size={16} /> Data
                </label>
                <input
                  required
                  type="date"
                  value={formData.date}
                  onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-white focus:ring-2 focus:ring-indigo-500 outline-none"
                />
              </div>
               <div className="space-y-2">
                <label className="text-xs uppercase font-bold text-slate-400 flex items-center gap-2">
                  <Ticket size={16} /> Costo (€)
                </label>
                <input
                  required
                  type="number"
                  step="0.01"
                  min="0"
                  value={formData.cost}
                  onChange={(e) => setFormData({ ...formData, cost: parseFloat(e.target.value) })}
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-white focus:ring-2 focus:ring-indigo-500 outline-none"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs uppercase font-bold text-slate-400 flex items-center gap-2">
                <MapPin size={16} /> Città / Luogo
              </label>
              <div className="relative">
                <input
                  required
                  type="text"
                  value={formData.city}
                  onChange={(e) => setFormData({ ...formData, city: e.target.value })}
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-white focus:ring-2 focus:ring-indigo-500 outline-none pr-12"
                  placeholder="Es. Milano, Fabrique"
                />
                <button
                  type="button"
                  onClick={handleEnrichLocation}
                  disabled={isLocating || !formData.band}
                  className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 text-indigo-400 hover:text-indigo-300 bg-slate-800/80 hover:bg-slate-700 rounded-lg transition-colors border border-slate-700 disabled:opacity-50"
                  title="Trova Venue Automaticamente (AI)"
                >
                  {isLocating ? (
                    <Loader2 size={16} className="animate-spin" />
                  ) : (
                    <MapPinned size={16} />
                  )}
                </button>
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs uppercase font-bold text-slate-400 flex items-center gap-2">
                <PartyPopper size={16} /> Nome Evento / Tour
              </label>
              <input
                type="text"
                value={formData.event}
                onChange={(e) => setFormData({ ...formData, event: e.target.value })}
                className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-white focus:ring-2 focus:ring-indigo-500 outline-none"
                placeholder="Es. SlamDunk Festival"
              />
            </div>

            {/* Formatting Toggle */}
            <div className="flex items-center justify-between bg-slate-800/50 p-3 rounded-xl border border-slate-700/30">
               <div className="flex items-center gap-2">
                 <Type size={16} className="text-indigo-400" />
                 <span className="text-sm text-slate-300">Formattazione Automatica</span>
               </div>
               <button
                 type="button"
                 onClick={() => setAutoFormat(!autoFormat)}
                 className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none ${autoFormat ? 'bg-indigo-600' : 'bg-slate-700'}`}
               >
                 <span
                   className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${autoFormat ? 'translate-x-6' : 'translate-x-1'}`}
                 />
               </button>
            </div>

            <button
              type="submit"
              className="w-full bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white font-bold py-4 rounded-xl shadow-lg shadow-indigo-500/20 transition-all transform active:scale-[0.98] mt-2 text-lg"
            >
              {initialData ? 'Salva Modifiche' : 'Aggiungi al Tracker'}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useConcerts } from './hooks/useConcerts';
import { Navbar } from './components/Navbar';
import { ConcertTable } from './components/ConcertTable';
import { Statistics } from './components/Statistics';
import { ConcertForm } from './components/ConcertForm';
import { Concert } from './types';
import { Loader2 } from 'lucide-react';

function App() {
  const { concerts, loading, addConcert, updateConcert, deleteConcert } = useConcerts();
  const [view, setView] = useState<'list' | 'stats'>('list');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingConcert, setEditingConcert] = useState<Concert | undefined>(undefined);

  const handleAddClick = () => {
    setEditingConcert(undefined);
    setIsFormOpen(true);
  };

  const handleEditClick = (concert: Concert) => {
    setEditingConcert(concert);
    setIsFormOpen(true);
  };

  const handleFormSubmit = (data: Omit<Concert, 'id'>) => {
    if (editingConcert) {
      updateConcert(editingConcert.id, data);
    } else {
      addConcert(data);
    }
  };

  return (
    <div className="min-h-screen bg-slate-900 text-slate-50 selection:bg-indigo-500 selection:text-white pb-32 md:pb-24">
      {/* Changed max-w-3xl to max-w-7xl for full width experience */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-6 md:pt-8">

        {/* Header */}
        <header className="mb-6 md:mb-8 flex flex-col md:flex-row md:items-end justify-between gap-4">
          <div>
            <h1 className="text-3xl md:text-5xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 via-purple-400 to-pink-400 animate-in fade-in slide-in-from-left-4 duration-700">
              My Concert Journal
            </h1>
            <p className="text-slate-400 text-sm md:text-base mt-2 max-w-xl leading-relaxed">
              Il tuo diario musicale digitale. 
              {loading ? (
                 <span className="inline-flex items-center gap-2 ml-2 text-indigo-400 animate-pulse">
                   <Loader2 size={14} className="animate-spin" /> Sync...
                 </span>
              ) : (
                 <> Hai partecipato a <strong className="text-white">{concerts.length}</strong> eventi finora.</>
              )}
            </p>
          </div>
        </header>

        {/* Main Content Area */}
        <main className="w-full">
          {loading && concerts.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-32 space-y-4">
              <Loader2 size={48} className="text-indigo-500 animate-spin" />
              <p className="text-slate-400 text-sm">Caricamento concerti dal cloud...</p>
            </div>
          ) : (
            <>
              {view === 'list' ? (
                <ConcertTable 
                  concerts={concerts} 
                  onEdit={handleEditClick} 
                  onDelete={deleteConcert}
                />
              ) : (
                <Statistics concerts={concerts} />
              )}
            </>
          )}
        </main>
      </div>

      {/* Floating UI Elements */}
      <ConcertForm
        isOpen={isFormOpen}
        onClose={() => setIsFormOpen(false)}
        onSubmit={handleFormSubmit}
        initialData={editingConcert}
      />

      <Navbar 
        currentView={view} 
        setView={setView} 
        onAddClick={handleAddClick} 
      />
    </div>
  );
}

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { X, Calendar, MapPin, Ticket, Music2, PartyPopper, Camera, Loader2, Sparkles, FileText, ImageIcon, Mail, FileType, Type, MapPinned } from 'lucide-react';
import { GoogleGenAI, Type as GenAiType } from "@google/genai";
import { Concert } from '../types';

interface ConcertFormProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: Omit<Concert, 'id'>) => void;
  initialData?: Concert;
}

const SPECIAL_UPPERCASE = ['WEL', 'WET', 'POE', 'PPMP', 'DJ', 'PR'];

export const ConcertForm: React.FC<ConcertFormProps> = ({ isOpen, onClose, onSubmit, initialData }) => {
  const [formData, setFormData] = useState({
    band: '',
    date: '',
    city: '',
    event: '',
    cost: 0,
  });

  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isLocating, setIsLocating] = useState(false);
  const [analysisMode, setAnalysisMode] = useState<'image' | 'text'>('image');
  const [emailText, setEmailText] = useState('');
  const [autoFormat, setAutoFormat] = useState(true); // Default to auto-format
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (initialData) {
      setFormData({
        band: initialData.band,
        date: initialData.date,
        city: initialData.city,
        event: initialData.event,
        cost: initialData.cost,
      });
    } else {
      setFormData({
        band: '',
        date: new Date().toISOString().split('T')[0],
        city: '',
        event: 'Concerto',
        cost: 0,
      });
      setEmailText('');
      setAutoFormat(true);
    }
  }, [initialData, isOpen]);

  // Helper to format a single string (Title Case with exceptions)
  const formatString = (str: string): string => {
    if (!str) return '';
    return str.split(' ').map(word => {
      // Remove punctuation for the check (e.g., "WEL," -> "WEL")
      const cleanWord = word.replace(/[^a-zA-Z0-9]/g, '').toUpperCase();

      // If it's a special word, return it fully uppercase (preserving original punctuation if needed is tricky, 
      // but simple replacement works for most cases. Let's rebuild the word carefully).
      if (SPECIAL_UPPERCASE.includes(cleanWord)) {
        return word.toUpperCase();
      }

      // Standard Title Case: First letter upper, rest lower
      return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
    }).join(' ');
  };

  // Helper specifically for comma-separated lists (like bands)
  const formatList = (str: string): string => {
    return str.split(',').map(part => formatString(part.trim())).join(', ');
  };

  const updateFormFromData = (data: any) => {
    setFormData(prev => ({
      ...prev,
      band: data.band || prev.band,
      date: data.date || prev.date,
      city: data.city || prev.city,
      event: data.event || prev.event,
      cost: typeof data.cost === 'number' ? data.cost : prev.cost
    }));
  };

  const openGmailSearch = () => {
    const query = encodeURIComponent("subject:(biglietti OR ticket OR ordine OR conferma OR order OR confirmation)");
    window.open(`https://mail.google.com/mail/u/0/#search/${query}`, '_blank');
  };

  const handleEnrichLocation = async () => {
    if (!formData.band || !formData.city) return;
    setIsLocating(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: {
          parts: [{
            text: `Identify the specific concert venue.
            Artist: ${formData.band}
            Date: ${formData.date}
            City: ${formData.city}
            Current Event Name: ${formData.event}

            Task: Return the specific venue name combined with the city.
            Format: "City, Venue Name" (e.g. "Milano, Fabrique" or "Parma, Parco Ducale").

            Rules:
            1. If the input City already contains the venue (e.g. "Milano, Fabrique"), return it as is.
            2. If you cannot find a specific venue for this date/artist in this city, return just the City.
            3. Prioritize famous venues (stadiums, clubs, parks).`
          }]
        },
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
            type: GenAiType.OBJECT,
            properties: {
              venue: { type: GenAiType.STRING }
            }
          }
        }
      });

      const result = JSON.parse(response.text || '{}');
      if (result.venue) {
        setFormData(prev => ({ ...prev, city: result.venue }));
      }
    } catch (e) {
      console.error("Error enriching location", e);
    } finally {
      setIsLocating(false);
    }
  };

  const handleTextAnalysis = async () => {
    if (!emailText.trim()) return;
    setIsAnalyzing(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: {
          parts: [
            {
              text: `Analyze the following text which is likely an email confirmation for a concert ticket or an event description. 
              Extract the details in JSON format using the schema provided.

              TEXT TO ANALYZE:
              "${emailText}"

              Instructions:
              - 'band': Main artist(s).
              - 'date': YYYY-MM-DD.
              - 'city': City name (Try to include venue if available, e.g. "Milano, Fabrique").
              - 'event': Event name.
              - 'cost': Total cost found in the text (number only).`
            }
          ]
        },
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
             type: GenAiType.OBJECT,
             properties: {
               band: { type: GenAiType.STRING },
               date: { type: GenAiType.STRING },
               city: { type: GenAiType.STRING },
               event: { type: GenAiType.STRING },
               cost: { type: GenAiType.NUMBER }
             }
          }
        }
      });

      const text = response.text;
      if (text) {
        updateFormFromData(JSON.parse(text));
      }
    } catch (error) {
      console.error("Error analyzing text:", error);
      alert("Errore durante l'analisi del testo. Riprova.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/') && file.type !== 'application/pdf') {
      alert("Per favore carica un'immagine o un file PDF.");
      return;
    }

    setIsAnalyzing(true);

    try {
      const base64Data = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => {
          const result = reader.result as string;
          const base64Content = result.split(',')[1];
          resolve(base64Content);
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: {
          parts: [
            {
              inlineData: {
                mimeType: file.type,
                data: base64Data
              }
            },
            {
              text: `Analyze this file (image or PDF document) of a concert ticket, receipt, or poster.
              CONTEXT FROM FILENAME: "${file.name}"
              Extract: band, date, city (include venue if visible), event, cost (number). JSON format.`
            }
          ]
        },
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
             type: GenAiType.OBJECT,
             properties: {
               band: { type: GenAiType.STRING },
               date: { type: GenAiType.STRING },
               city: { type: GenAiType.STRING },
               event: { type: GenAiType.STRING },
               cost: { type: GenAiType.NUMBER }
             }
          }
        }
      });

      const text = response.text;
      if (text) {
        updateFormFromData(JSON.parse(text));
      }

    } catch (error) {
      console.error("Error analyzing file:", error);
      alert("Impossibile analizzare il file.");
    } finally {
      setIsAnalyzing(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const dateObj = new Date(formData.date);
    const year = dateObj.getFullYear();

    // Auto-formatting logic
    let finalBand = formData.band;
    let finalCity = formData.city;
    let finalEvent = formData.event;

    if (autoFormat) {
      finalBand = formatList(formData.band);
      finalCity = formatString(formData.city);
      finalEvent = formatString(formData.event);
    }

    // Auto-calculate artists count based on commas
    const artistCount = finalBand
      .split(',')
      .map(s => s.trim())
      .filter(s => s.length > 0)
      .length;

    const finalArtists = artistCount > 0 ? artistCount : 1;

    // Normalize Event Name for PPMP (Specific logic override)
    const lowerEvent = finalEvent.toLowerCase().trim();
    if (lowerEvent === 'ppmp' || lowerEvent === 'pop punk mosh party') {
       finalEvent = 'PPMP - Pop Punk Mosh Party';
    }

    onSubmit({
      ...formData,
      band: finalBand,
      city: finalCity,
      event: finalEvent,
      artists: finalArtists,
      year,
    });
    onClose();
  };

  if (!isOpen) return null;

  return (
    // Mobile: Aligns to bottom (items-end), Desktop: Centered (md:items-center)
    <div className="fixed inset-0 z-[60] flex items-end md:items-center justify-center sm:p-4 bg-black/80 backdrop-blur-md transition-all duration-300">
      <div className="bg-slate-900 border border-slate-700 w-full h-[90vh] md:h-auto md:max-w-lg rounded-t-3xl md:rounded-2xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-10 fade-in duration-300 md:zoom-in-95 md:slide-in-from-bottom-0 flex flex-col">

        {/* Header */}
        <div className="p-5 md:p-6 border-b border-slate-800 flex justify-between items-center bg-slate-800/50 sticky top-0 backdrop-blur-sm z-10 shrink-0">
          <div>
            <h2 className="text-xl md:text-2xl font-bold text-white">
              {initialData ? 'Modifica Evento' : 'Nuovo Evento'}
            </h2>
            <p className="text-xs text-slate-400 mt-0.5">
              Inserisci i dettagli del concerto.
            </p>
          </div>
          <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-800 text-slate-400 hover:text-white transition-colors">
            <X size={24} />
          </button>
        </div>

        {/* Scrollable Content */}
        <div className="p-5 md:p-6 space-y-6 overflow-y-auto custom-scrollbar flex-1">

          {/* AI Import Section */}
          {!initialData && (
             <div className="bg-slate-800/50 p-4 rounded-xl border border-slate-700/50 space-y-4">
               <div className="flex items-center justify-between">
                  <h3 className="text-sm font-bold text-indigo-300 flex items-center gap-2">
                    <Sparkles size={14} /> Importazione Automatica
                  </h3>

                  <div className="flex bg-slate-900 rounded-lg p-1 border border-slate-700">
                    <button 
                      type="button"
                      onClick={() => setAnalysisMode('image')}
                      className={`p-1.5 rounded-md transition-all ${analysisMode === 'image' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                    >
                      <FileType size={16} />
                    </button>
                    <button 
                      type="button"
                      onClick={() => setAnalysisMode('text')}
                      className={`p-1.5 rounded-md transition-all ${analysisMode === 'text' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                    >
                      <FileText size={16} />
                    </button>
                  </div>
               </div>

               {analysisMode === 'image' ? (
                 <div className="flex flex-col sm:flex-row items-center justify-between gap-4 animate-in fade-in duration-300">
                   <p className="text-[10px] text-slate-400 w-full sm:w-auto">
                     Carica biglietto o locandina.
                   </p>
                   <input 
                     type="file" 
                     ref={fileInputRef} 
                     onChange={handleFileChange} 
                     accept="image/*,application/pdf" 
                     className="hidden" 
                   />
                   <button
                     type="button"
                     onClick={() => fileInputRef.current?.click()}
                     disabled={isAnalyzing}
                     className="w-full sm:w-auto flex items-center justify-center gap-2 bg-slate-700 hover:bg-slate-600 text-white text-xs font-bold py-2.5 px-4 rounded-lg transition-colors shadow-sm whitespace-nowrap"
                   >
                     {isAnalyzing ? (
                       <><Loader2 size={16} className="animate-spin" /> Analisi...</>
                     ) : (
                       <><FileType size={16} /> Carica File</>
                     )}
                   </button>
                 </div>
               ) : (
                 <div className="space-y-3 animate-in fade-in duration-300">
                   <div className="flex justify-between items-center">
                     <p className="text-[10px] text-slate-400">
                       Incolla qui il testo.
                     </p>
                     <button 
                        type="button"
                        onClick={openGmailSearch}
                        className="text-[10px] text-indigo-400 hover:text-indigo-300 flex items-center gap-1 font-semibold transition-colors"
                     >
                        <Mail size={12} /> Cerca Gmail
                     </button>
                   </div>
                   <textarea
                     value={emailText}
                     onChange={(e) => setEmailText(e.target.value)}
                     placeholder="Incolla il testo qui..."
                     className="w-full h-20 bg-slate-900/80 border border-slate-700 rounded-lg p-3 text-xs text-white placeholder:text-slate-600 focus:ring-1 focus:ring-indigo-500 outline-none resize-none"
                   />
                   <button
                     type="button"
                     onClick={handleTextAnalysis}
                     disabled={isAnalyzing || !emailText.trim()}
                     className="w-full flex items-center justify-center gap-2 bg-slate-700 hover:bg-slate-600 disabled:opacity-50 text-white text-xs font-bold py-2.5 px-4 rounded-lg transition-colors shadow-sm"
                   >
                     {isAnalyzing ? (
                       <><Loader2 size={16} className="animate-spin" /> Elaborazione...</>
                     ) : (
                       <><Sparkles size={16} /> Estrai Dati</>
                     )}
                   </button>
                 </div>
               )}
             </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-5 md:space-y-6">

            <div className="space-y-2">
              <label className="text-xs uppercase font-bold text-indigo-400 flex items-center gap-2">
                <Music2 size={16} /> Artisti (Separati da virgola)
              </label>
              <input
                required
                type="text"
                value={formData.band}
                onChange={(e) => setFormData({ ...formData, band: e.target.value })}
                className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3.5 md:p-4 text-base md:text-lg text-white focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all placeholder:text-slate-600"
                placeholder="Es. Simple Plan, Sum 41"
              />
            </div>

            <div className="grid grid-cols-2 gap-4 md:gap-6">
              <div className="space-y-2">
                <label className="text-xs uppercase font-bold text-slate-400 flex items-center gap-2">
                  <Calendar size={16} /> Data
                </label>
                <input
                  required
                  type="date"
                  value={formData.date}
                  onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-white focus:ring-2 focus:ring-indigo-500 outline-none"
                />
              </div>
               <div className="space-y-2">
                <label className="text-xs uppercase font-bold text-slate-400 flex items-center gap-2">
                  <Ticket size={16} /> Costo (€)
                </label>
                <input
                  required
                  type="number"
                  step="0.01"
                  min="0"
                  value={formData.cost}
                  onChange={(e) => setFormData({ ...formData, cost: parseFloat(e.target.value) })}
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-white focus:ring-2 focus:ring-indigo-500 outline-none"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs uppercase font-bold text-slate-400 flex items-center gap-2">
                <MapPin size={16} /> Città / Luogo
              </label>
              <div className="relative">
                <input
                  required
                  type="text"
                  value={formData.city}
                  onChange={(e) => setFormData({ ...formData, city: e.target.value })}
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-white focus:ring-2 focus:ring-indigo-500 outline-none pr-12"
                  placeholder="Es. Milano, Fabrique"
                />
                <button
                  type="button"
                  onClick={handleEnrichLocation}
                  disabled={isLocating || !formData.band}
                  className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 text-indigo-400 hover:text-indigo-300 bg-slate-800/80 hover:bg-slate-700 rounded-lg transition-colors border border-slate-700 disabled:opacity-50"
                  title="Trova Venue Automaticamente (AI)"
                >
                  {isLocating ? (
                    <Loader2 size={16} className="animate-spin" />
                  ) : (
                    <MapPinned size={16} />
                  )}
                </button>
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs uppercase font-bold text-slate-400 flex items-center gap-2">
                <PartyPopper size={16} /> Nome Evento / Tour
              </label>
              <input
                type="text"
                value={formData.event}
                onChange={(e) => setFormData({ ...formData, event: e.target.value })}
                className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-white focus:ring-2 focus:ring-indigo-500 outline-none"
                placeholder="Es. SlamDunk Festival"
              />
            </div>

            {/* Formatting Toggle */}
            <div className="flex items-center justify-between bg-slate-800/50 p-3 rounded-xl border border-slate-700/30">
               <div className="flex items-center gap-2">
                 <Type size={16} className="text-indigo-400" />
                 <span className="text-sm text-slate-300">Formattazione Automatica</span>
               </div>
               <button
                 type="button"
                 onClick={() => setAutoFormat(!autoFormat)}
                 className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors focus:outline-none ${autoFormat ? 'bg-indigo-600' : 'bg-slate-700'}`}
               >
                 <span
                   className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${autoFormat ? 'translate-x-6' : 'translate-x-1'}`}
                 />
               </button>
            </div>

            <button
              type="submit"
              className="w-full bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white font-bold py-3.5 md:py-4 rounded-xl shadow-lg shadow-indigo-500/20 transition-all transform active:scale-[0.98] mt-2 text-lg pb-safe"
            >
              {initialData ? 'Salva Modifiche' : 'Aggiungi al Tracker'}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Concert, PriceRange } from '../types';
import { Search, MapPin, Calendar, Edit2, Trash2, Tag, Filter, X, ChevronDown, Mic2, Users } from 'lucide-react';

interface ConcertTableProps {
  concerts: Concert[];
  onEdit: (concert: Concert) => void;
  onDelete: (id: string) => void;
}

export const ConcertTable: React.FC<ConcertTableProps> = ({ concerts, onEdit, onDelete }) => {
  const [search, setSearch] = useState('');
  const [sortField, setSortField] = useState<'date' | 'cost'>('date');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');

  // Advanced Filters State
  const [showFilters, setShowFilters] = useState(false);
  const [selectedYear, setSelectedYear] = useState<string>('all');
  const [selectedType, setSelectedType] = useState<string>('all');
  const [selectedPrice, setSelectedPrice] = useState<PriceRange>('all');
  const [selectedArtist, setSelectedArtist] = useState<string>('all');

  // Normalization helpers
  const normalizeArtist = (name: string) => {
    const n = name.trim();
    const lower = n.toLowerCase();
    if (lower.replace(/\s/g, '') === 'bnkr44') return 'Bnkr44';
    if (lower === 'wel') return 'WEL';
    if (lower === 'wet') return 'WET';
    if (lower === 'poe') return 'POE';

    // Standard Title Case for filter grouping
    return n.split(' ').map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase()).join(' ');
  };

  const normalizeEvent = (event: string) => {
    const e = event.trim();
    const lower = e.toLowerCase();
    // Inclusive check for PPMP to handle simple "PPMP" or full "PPMP - Pop Punk Mosh Party"
    if (lower.includes('ppmp') || lower.includes('pop punk mosh party')) return 'PPMP - Pop Punk Mosh Party';
    if (lower === 'blaster') return 'Blaster';
    return e;
  };

  // Derive unique options for filters
  const availableYears = useMemo(() => {
    const years = Array.from(new Set(concerts.map(c => c.year))).sort((a, b) => b - a);
    return years;
  }, [concerts]);

  const availableTypes = useMemo(() => {
    const types = new Set<string>();
    concerts.forEach(c => {
       types.add(normalizeEvent(c.event));
    });
    return Array.from(types).sort();
  }, [concerts]);

  // Derive unique artists (splitting by comma)
  const availableArtists = useMemo(() => {
    const allArtists = new Set<string>();
    concerts.forEach(c => {
      c.band.split(',').forEach(artist => {
        allArtists.add(normalizeArtist(artist));
      });
    });
    return Array.from(allArtists).sort((a, b) => a.localeCompare(b));
  }, [concerts]);

  const filteredAndSortedConcerts = useMemo(() => {
    let result = [...concerts];

    // 1. Search Text
    if (search) {
      const lowerSearch = search.toLowerCase();
      result = result.filter(
        c => 
          c.band.toLowerCase().includes(lowerSearch) || 
          c.city.toLowerCase().includes(lowerSearch) ||
          c.event.toLowerCase().includes(lowerSearch)
      );
    }

    // 2. Year Filter
    if (selectedYear !== 'all') {
      result = result.filter(c => c.year === parseInt(selectedYear));
    }

    // 3. Type Filter
    if (selectedType !== 'all') {
      result = result.filter(c => normalizeEvent(c.event) === selectedType);
    }

    // 4. Price Filter
    if (selectedPrice !== 'all') {
      switch (selectedPrice) {
        case 'free': result = result.filter(c => c.cost === 0); break;
        case 'under-30': result = result.filter(c => c.cost > 0 && c.cost < 30); break;
        case '30-60': result = result.filter(c => c.cost >= 30 && c.cost <= 60); break;
        case 'over-60': result = result.filter(c => c.cost > 60); break;
      }
    }

    // 5. Artist Filter
    if (selectedArtist !== 'all') {
      result = result.filter(c => {
        // Check if ANY of the artists in the band string match the selected artist (normalized)
        const artists = c.band.split(',').map(s => normalizeArtist(s));
        return artists.includes(selectedArtist);
      });
    }

    // 6. Sorting
    result.sort((a, b) => {
      let valA, valB;

      if (sortField === 'date') {
        valA = new Date(a.date).getTime();
        valB = new Date(b.date).getTime();
      } else {
        valA = a.cost;
        valB = b.cost;
      }

      return sortOrder === 'asc' ? valA - valB : valB - valA;
    });

    return result;
  }, [concerts, search, sortField, sortOrder, selectedYear, selectedType, selectedPrice, selectedArtist]);

  const toggleSort = (field: 'date' | 'cost') => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder('desc'); 
    }
  };

  const getDayAndMonth = (dateStr: string) => {
    try {
      const d = new Date(dateStr);
      const day = d.getDate();
      const month = d.toLocaleDateString('it-IT', { month: 'short' }).toUpperCase();
      const year = d.getFullYear();
      return { day, month, year };
    } catch {
      return { day: '?', month: '???', year: '????' };
    }
  };

  const clearFilters = () => {
    setSearch('');
    setSelectedYear('all');
    setSelectedType('all');
    setSelectedPrice('all');
    setSelectedArtist('all');
  };

  const activeFiltersCount = 
    (selectedYear !== 'all' ? 1 : 0) + 
    (selectedType !== 'all' ? 1 : 0) + 
    (selectedPrice !== 'all' ? 1 : 0) + 
    (selectedArtist !== 'all' ? 1 : 0);

  return (
    <div className="space-y-6">

      {/* Search and Sort Bar */}
      <div className="sticky top-0 z-30 pt-4 -mx-2 px-2 pb-4 bg-gradient-to-b from-slate-900 via-slate-900/95 to-transparent">
        <div className="flex flex-col gap-3 max-w-4xl mx-auto lg:max-w-none">

          <div className="flex flex-col sm:flex-row gap-2 w-full">
            <div className="relative flex-1 group">
              <div className="absolute inset-0 bg-gradient-to-r from-indigo-500 to-purple-600 rounded-xl blur opacity-25 group-hover:opacity-40 transition duration-300"></div>
              <div className="relative bg-slate-900 rounded-xl flex items-center border border-slate-700 focus-within:border-indigo-500 transition-colors">
                <Search className="ml-4 text-slate-400" size={20} />
                <input
                  type="text"
                  placeholder="Cerca band, città..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="w-full bg-transparent text-white py-3 px-3 outline-none placeholder-slate-500"
                />
                {search && (
                  <button onClick={() => setSearch('')} className="mr-3 text-slate-500 hover:text-white">
                    <X size={16} />
                  </button>
                )}
              </div>
            </div>

            {/* Filter Toggle */}
            <button 
              onClick={() => setShowFilters(!showFilters)}
              className={`relative px-4 py-3 sm:py-0 rounded-xl border transition-all flex items-center justify-center gap-2 ${
                showFilters || activeFiltersCount > 0
                  ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg shadow-indigo-900/20' 
                  : 'bg-slate-800 border-slate-700 text-slate-300 hover:bg-slate-700'
              }`}
            >
              <Filter size={20} />
              <span className="inline">Filtri</span>
              {activeFiltersCount > 0 && (
                <span className="absolute -top-2 -right-2 bg-pink-500 text-white text-[10px] font-bold w-5 h-5 flex items-center justify-center rounded-full border border-slate-900">
                  {activeFiltersCount}
                </span>
              )}
            </button>
          </div>

          {/* Data Count */}
          <div className="flex justify-end px-1">
             <div className="text-[10px] text-slate-500 italic">
               {filteredAndSortedConcerts.length} eventi visualizzati
             </div>
          </div>

          {/* Expanded Filter Dashboard */}
          <div className={`overflow-hidden transition-all duration-300 ease-in-out ${showFilters ? 'max-h-[800px] opacity-100' : 'max-h-0 opacity-0'}`}>
            <div className="glass-panel p-4 rounded-xl space-y-4 mt-2">
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">

                {/* Artist Filter */}
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Artista / Band</label>
                  <div className="relative">
                    <select 
                      value={selectedArtist}
                      onChange={(e) => setSelectedArtist(e.target.value)}
                      className="w-full appearance-none bg-slate-900 border border-slate-700 text-white rounded-lg py-2 px-3 focus:ring-2 focus:ring-indigo-500 outline-none text-sm"
                    >
                      <option value="all">Tutti gli artisti</option>
                      {availableArtists.map(artist => (
                        <option key={artist} value={artist}>{artist}</option>
                      ))}
                    </select>
                    <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" size={14} />
                  </div>
                </div>

                {/* Type Filter */}
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Evento</label>
                  <div className="relative">
                    <select 
                      value={selectedType}
                      onChange={(e) => setSelectedType(e.target.value)}
                      className="w-full appearance-none bg-slate-900 border border-slate-700 text-white rounded-lg py-2 px-3 focus:ring-2 focus:ring-indigo-500 outline-none text-sm capitalize"
                    >
                      <option value="all">Tutti i tipi</option>
                      {availableTypes.map(t => (
                        <option key={t} value={t}>{t}</option>
                      ))}
                    </select>
                    <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" size={14} />
                  </div>
                </div>

                {/* Price Filter */}
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Costo</label>
                  <div className="relative">
                    <select 
                      value={selectedPrice}
                      onChange={(e) => setSelectedPrice(e.target.value as PriceRange)}
                      className="w-full appearance-none bg-slate-900 border border-slate-700 text-white rounded-lg py-2 px-3 focus:ring-2 focus:ring-indigo-500 outline-none text-sm"
                    >
                      <option value="all">Tutti i prezzi</option>
                      <option value="free">Gratis</option>
                      <option value="under-30">&lt; €30</option>
                      <option value="30-60">€30 - €60</option>
                      <option value="over-60">&gt; €60</option>
                    </select>
                    <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" size={14} />
                  </div>
                </div>

                {/* Year Filter */}
                <div className="space-y-1">
                  <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Anno</label>
                  <div className="relative">
                    <select 
                      value={selectedYear}
                      onChange={(e) => setSelectedYear(e.target.value)}
                      className="w-full appearance-none bg-slate-900 border border-slate-700 text-white rounded-lg py-2 px-3 focus:ring-2 focus:ring-indigo-500 outline-none text-sm"
                    >
                      <option value="all">Tutti gli anni</option>
                      {availableYears.map(y => (
                        <option key={y} value={y}>{y}</option>
                      ))}
                    </select>
                    <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" size={14} />
                  </div>
                </div>

              </div>

              {/* Quick Sort Actions within filter area */}
              <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center border-t border-slate-700/50 pt-3 gap-3">
                <div className="flex gap-2 w-full sm:w-auto">
                   <button 
                    onClick={() => toggleSort('date')}
                    className={`flex-1 sm:flex-none flex justify-center items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                      sortField === 'date' ? 'bg-indigo-600/20 text-indigo-300 border border-indigo-500/30' : 'text-slate-400 hover:text-white'
                    }`}
                  >
                    <Calendar size={12} /> Data {sortField === 'date' && (sortOrder === 'asc' ? '↑' : '↓')}
                  </button>
                  <button 
                    onClick={() => toggleSort('cost')}
                    className={`flex-1 sm:flex-none flex justify-center items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                      sortField === 'cost' ? 'bg-indigo-600/20 text-indigo-300 border border-indigo-500/30' : 'text-slate-400 hover:text-white'
                    }`}
                  >
                    <Tag size={12} /> Costo {sortField === 'cost' && (sortOrder === 'asc' ? '↑' : '↓')}
                  </button>
                </div>
                <button onClick={clearFilters} className="text-xs text-slate-500 hover:text-white underline decoration-slate-600 underline-offset-2 w-full sm:w-auto text-center">
                  Reset Filtri
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Grid Layout to fill screen edges */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredAndSortedConcerts.length === 0 ? (
          <div className="col-span-full flex flex-col items-center justify-center py-20 text-slate-500 animate-in fade-in zoom-in duration-500">
            <div className="w-20 h-20 bg-slate-800/50 rounded-full flex items-center justify-center mb-4">
              <Mic2 size={40} className="text-slate-600" />
            </div>
            <p className="text-lg font-medium">Nessun concerto trovato.</p>
            <p className="text-sm">Prova a cambiare i filtri.</p>
            <button onClick={clearFilters} className="mt-4 px-4 py-2 bg-indigo-600 text-white rounded-lg text-sm hover:bg-indigo-500 transition-colors">
              Mostra tutti
            </button>
          </div>
        ) : (
          filteredAndSortedConcerts.map((concert, index) => {
            const { day, month, year } = getDayAndMonth(concert.date);
            // Calculate delay for staggered animation based on index (max 10 items)
            const animationDelay = index < 15 ? `${index * 0.05}s` : '0s';

            return (
              <div 
                key={concert.id}
                className="animate-card group relative bg-slate-800 rounded-2xl overflow-hidden shadow-lg hover:shadow-2xl hover:shadow-indigo-900/20 transition-all duration-300 border border-slate-700/50 hover:border-indigo-500/30 flex flex-col h-full"
                style={{ animationDelay }}
              >
                {/* Background Decoration */}
                <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-600/5 rounded-full blur-3xl -mr-10 -mt-10 pointer-events-none"></div>

                {/* Card Header with Date and Price */}
                <div className="flex bg-slate-900/50 border-b border-slate-700/50">
                   {/* Date Stub */}
                   <div className="p-4 flex flex-col items-center justify-center border-r border-slate-700/50 min-w-[80px]">
                      <span className="text-xl font-black text-white">{day}</span>
                      <span className="text-xs font-bold text-indigo-400 uppercase tracking-widest">{month}</span>
                      <span className="text-[10px] text-slate-500 mt-1">{year}</span>
                   </div>

                   {/* Top Info */}
                   <div className="flex-1 p-3 flex justify-between items-center gap-4 overflow-hidden">
                      <div className="px-2 py-1 rounded-md bg-slate-700/50 border border-slate-600/50 text-[10px] font-bold uppercase text-slate-300 tracking-wider truncate" title={concert.event}>
                          {concert.event}
                      </div>
                      <div className="text-right shrink-0">
                         <div className={`font-bold text-lg leading-tight ${concert.cost === 0 ? 'text-green-400' : 'text-white'}`}>
