import React, { useState } from 'react';
import { useConcerts } from './hooks/useConcerts';
import { useAuth } from './hooks/useAuth';
import { Navbar } from './components/Navbar';
import { ConcertTable } from './components/ConcertTable';
import { Statistics } from './components/Statistics';
import { ConcertForm } from './components/ConcertForm';
import { AuthModal } from './components/AuthModal';
import { Concert } from './types';
import { Loader2, Ticket } from 'lucide-react';

function App() {
  const { concerts, loading, addConcert, updateConcert, deleteConcert } = useConcerts();
  const { user, signOut } = useAuth();

  const [view, setView] = useState<'list' | 'stats'>('list');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [isAuthOpen, setIsAuthOpen] = useState(false);
  const [editingConcert, setEditingConcert] = useState<Concert | undefined>(undefined);

  const handleAddClick = () => {
    setEditingConcert(undefined);
    setIsFormOpen(true);
  };

  const handleEditClick = (concert: Concert) => {
    setEditingConcert(concert);
    setIsFormOpen(true);
  };

  const handleFormSubmit = (data: Omit<Concert, 'id'>) => {
    if (editingConcert) {
      updateConcert(editingConcert.id, data);
    } else {
      addConcert(data);
    }
  };

  return (
    <div className="min-h-screen bg-slate-900 text-slate-50 selection:bg-indigo-500 selection:text-white pb-32 md:pb-24">
      {/* Changed max-w-3xl to max-w-7xl for full width experience */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-6 md:pt-12">

        {/* Header - Centered as requested */}
        <header className="mb-8 md:mb-12 flex flex-col items-center text-center gap-4">
          <div className="animate-in zoom-in duration-700 delay-100 relative group">
             <div className="absolute inset-0 bg-indigo-500 blur-2xl opacity-20 group-hover:opacity-30 transition-opacity rounded-full"></div>
             <div className="relative p-4 bg-slate-800/50 rounded-2xl border border-slate-700/50 shadow-2xl backdrop-blur-sm transform group-hover:scale-105 transition-transform duration-300">
               <Ticket size={48} className="text-indigo-400 drop-shadow-[0_0_15px_rgba(129,140,248,0.5)]" />
             </div>
          </div>
          <div>
            <h1 className="text-4xl md:text-6xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 via-purple-400 to-pink-400 animate-in fade-in slide-in-from-top-4 duration-700">
              My Concert Journal
            </h1>
            <p className="text-slate-400 text-sm md:text-lg mt-3 max-w-2xl mx-auto leading-relaxed">
              Il tuo diario musicale digitale. 
              {loading ? (
                 <span className="inline-flex items-center gap-2 ml-2 text-indigo-400 animate-pulse">
                   <Loader2 size={14} className="animate-spin" /> Sync...
                 </span>
              ) : (
                 <> Hai partecipato a <strong className="text-white">{concerts.length}</strong> eventi finora.</>
              )}
            </p>
          </div>
        </header>

        {/* Main Content Area */}
        <main className="w-full">
          {loading && concerts.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-32 space-y-4">
              <Loader2 size={48} className="text-indigo-500 animate-spin" />
              <p className="text-slate-400 text-sm">Caricamento concerti dal cloud...</p>
            </div>
          ) : (
            <>
              {view === 'list' ? (
                <ConcertTable 
                  concerts={concerts} 
                  onEdit={handleEditClick} 
                  onDelete={deleteConcert}
                  user={user}
                />
              ) : (
                <Statistics concerts={concerts} />
              )}
            </>
          )}
        </main>
      </div>

      {/* Floating UI Elements */}
      {user && (
        <ConcertForm
          isOpen={isFormOpen}
          onClose={() => setIsFormOpen(false)}
          onSubmit={handleFormSubmit}
          initialData={editingConcert}
        />
      )}

      <AuthModal 
        isOpen={isAuthOpen} 
        onClose={() => setIsAuthOpen(false)} 
      />

      <Navbar 
        currentView={view} 
        setView={setView} 
        onAddClick={handleAddClick}
        user={user}
        onLoginClick={() => setIsAuthOpen(true)}
        onLogoutClick={() => {
           if(window.confirm("Vuoi davvero uscire?")) signOut();
        }}
      />
    </div>
  );
}

export default App;

import { useState, useEffect } from 'react';
import { supabase } from '../supabaseClient';
import { User, browserLocalPersistence, browserSessionPersistence } from '@supabase/supabase-js';

export const useAuth = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Check active session
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
      setLoading(false);
    });

    // Listen for changes (login, logout, etc.)
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
      setLoading(false);
    });

    return () => subscription.unsubscribe();
  }, []);

  const signIn = async (email: string, password: string, rememberMe: boolean = false) => {
    // Set persistence based on user preference before signing in
    await supabase.auth.setPersistence(rememberMe ? browserLocalPersistence : browserSessionPersistence);

    const { error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) throw error;
  };

  const signOut = async () => {
    const { error } = await supabase.auth.signOut();
    if (error) throw error;
  };

  const resetPassword = async (email: string) => {
    const { error } = await supabase.auth.resetPasswordForEmail(email, {
      redirectTo: window.location.origin, // Redirects back to app to handle password update
    });
    if (error) throw error;
  };

  return { user, loading, signIn, signOut, resetPassword };
};

import React, { useState } from 'react';
import { X, Mail, Lock, Loader2, LogIn, KeyRound, Check } from 'lucide-react';
import { useAuth } from '../hooks/useAuth';

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const AuthModal: React.FC<AuthModalProps> = ({ isOpen, onClose }) => {
  const { signIn, resetPassword } = useAuth();
  const [mode, setMode] = useState<'login' | 'reset'>('login');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(false);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<{ type: 'error' | 'success', text: string } | null>(null);

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage(null);

    try {
      if (mode === 'login') {
        await signIn(email, password, rememberMe);
        onClose(); // Close modal on success
      } else {
        await resetPassword(email);
        setMessage({ type: 'success', text: 'Ti abbiamo inviato una mail per resettare la password.' });
      }
    } catch (err: any) {
      setMessage({ type: 'error', text: err.message || 'Si è verificato un errore.' });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-300">
      <div className="bg-slate-900 border border-slate-700 w-full max-w-sm rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">

        <div className="p-5 border-b border-slate-800 flex justify-between items-center bg-slate-800/50">
          <h2 className="text-xl font-bold text-white flex items-center gap-2">
            {mode === 'login' ? <LogIn size={20} className="text-indigo-400" /> : <KeyRound size={20} className="text-indigo-400" />}
            {mode === 'login' ? 'Accedi' : 'Recupera Password'}
          </h2>
          <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-800 text-slate-400 hover:text-white transition-colors">
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          {message && (
            <div className={`p-3 rounded-lg text-xs border ${message.type === 'error' ? 'bg-red-500/10 border-red-500/50 text-red-200' : 'bg-green-500/10 border-green-500/50 text-green-200'}`}>
              {message.text}
            </div>
          )}

          <div className="space-y-2">
            <label className="text-xs uppercase font-bold text-slate-400">Email</label>
            <div className="relative">
              <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={16} />
              <input
                type="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full bg-slate-950 border border-slate-700 rounded-xl py-3 pl-10 pr-3 text-white focus:ring-2 focus:ring-indigo-500 outline-none"
                placeholder="nome@esempio.com"
              />
            </div>
          </div>

          {mode === 'login' && (
            <div className="space-y-2 animate-in fade-in slide-in-from-top-2">
              <label className="text-xs uppercase font-bold text-slate-400">Password</label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={16} />
                <input
                  type="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl py-3 pl-10 pr-3 text-white focus:ring-2 focus:ring-indigo-500 outline-none"
                  placeholder="••••••••"
                />
              </div>

              {/* Remember Me Checkbox */}
              <div 
                className="flex items-center gap-2 pt-2 cursor-pointer group w-max"
                onClick={() => setRememberMe(!rememberMe)}
              >
                 <div className={`w-5 h-5 rounded border flex items-center justify-center transition-all ${rememberMe ? 'bg-indigo-600 border-indigo-600' : 'bg-transparent border-slate-600 group-hover:border-indigo-500'}`}>
                    {rememberMe && <Check size={14} className="text-white stroke-[3]" />}
                 </div>
                 <span className="text-sm text-slate-300 group-hover:text-indigo-300 transition-colors select-none">
                   Ricordami
                 </span>
              </div>
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-indigo-600 hover:bg-indigo-500 text-white font-bold py-3 rounded-xl shadow-lg transition-transform active:scale-[0.98] mt-2 flex justify-center items-center gap-2"
          >
            {loading && <Loader2 size={16} className="animate-spin" />}
            {mode === 'login' ? 'Entra' : 'Invia Email di Reset'}
          </button>

          <div className="text-center mt-4">
            <button
              type="button"
              onClick={() => {
                setMode(mode === 'login' ? 'reset' : 'login');
                setMessage(null);
              }}
              className="text-xs text-slate-400 hover:text-white underline decoration-slate-600 underline-offset-2 transition-colors"
            >
              {mode === 'login' ? 'Password dimenticata?' : 'Torna al login'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

import { useState, useEffect } from 'react';
import { supabase } from '../supabaseClient';
import { User } from '@supabase/supabase-js';

export const useAuth = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Check active session
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
      setLoading(false);
    });

    // Listen for changes (login, logout, etc.)
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
      setLoading(false);
    });

    return () => subscription.unsubscribe();
  }, []);

  const signIn = async (email: string, password: string, _rememberMe: boolean = false) => {
    // Note: 'rememberMe' functionality regarding session persistence is disabled 
    // because 'setPersistence' is not available on the SupabaseAuthClient instance 
    // in this version, and we are using the global client instance.
    // The session will default to the client's configured persistence (usually LocalStorage).

    const { error } = await supabase.auth.signInWithPassword({ email, password });
    if (error) throw error;
  };

  const signOut = async () => {
    const { error } = await supabase.auth.signOut();
    if (error) throw error;
  };

  const resetPassword = async (email: string) => {
    const { error } = await supabase.auth.resetPasswordForEmail(email, {
      redirectTo: window.location.origin, // Redirects back to app to handle password update
    });
    if (error) throw error;
  };

  return { user, loading, signIn, signOut, resetPassword };
};
